/* Component source: shared-court-popup.css */
/* Shared court assignment dialog — all tournament formats */
.scs-court-popup-overlay{position:fixed;inset:0;z-index:2147483000;display:flex;align-items:center;justify-content:center;padding:16px;background:rgba(5,12,27,.76)}
.scs-court-popup{width:min(100%,420px);max-height:85dvh;overflow:auto;padding:18px;border:1px solid #6382b1;border-radius:18px;background:#1e304c;color:#f5f7ff;box-shadow:0 20px 70px rgba(0,0,0,.55);box-sizing:border-box}
.scs-court-popup-head{display:flex;align-items:center;justify-content:space-between;gap:10px}.scs-court-popup-head h3{margin:0;font-size:1.25rem}.scs-court-popup-head button{border:1px solid #7288ad;border-radius:9px;background:transparent;color:inherit;font-size:1.5rem;padding:2px 12px}
.scs-court-popup p{color:#bdcde7;overflow-wrap:anywhere}.scs-court-popup-choices{display:grid;gap:9px;margin:15px 0}.scs-court-popup-option,.scs-court-popup-cancel{width:100%;border:1px solid #7190bc;border-radius:11px;padding:12px 14px;text-align:left;background:#2c4a73;color:white;font:inherit}.scs-court-popup-option:disabled{opacity:.52;cursor:not-allowed}.scs-court-popup-cancel{text-align:center;background:#273b5a}
/* V398: non-blocking confirmation shown only after a successful court assignment. */
.scs-court-confirmation{position:fixed;inset:0;z-index:2147483001;display:flex;align-items:center;justify-content:center;padding:18px;pointer-events:none;background:rgba(5,12,27,.22)}
.scs-court-confirmation-panel{display:flex;flex-direction:column;align-items:center;gap:10px;width:min(100%,330px);padding:24px 20px;border-radius:18px;border:1px solid #568e9c;background:#1e304c;color:#f5f7ff;text-align:center;box-shadow:0 18px 55px rgba(0,0,0,.4);animation:scs-court-confirm-in .24s ease-out both}
.scs-court-confirmation-check{display:grid;place-items:center;width:58px;height:58px;border-radius:50%;background:#166b58;color:#b5ffe1;font-size:36px;font-weight:700;animation:scs-court-confirm-pop .34s ease-out both}
.scs-court-confirmation-panel strong{color:#79ebbd;font-size:1.35rem}
.scs-court-confirmation-match{font-weight:650;font-size:1.05rem;overflow-wrap:anywhere}
.scs-court-confirmation-location{width:100%;padding:11px;border-radius:11px;background:#2c4a73;box-sizing:border-box;font-weight:650}
.scs-court-confirmation-hint{color:#c2d6ee;font-size:.9rem}
@keyframes scs-court-confirm-in{from{opacity:0;transform:translateY(14px) scale(.96)}to{opacity:1;transform:translateY(0) scale(1)}}
@keyframes scs-court-confirm-pop{from{transform:scale(.65)}to{transform:scale(1)}}
@media(prefers-reduced-motion:reduce){.scs-court-confirmation-panel,.scs-court-confirmation-check{animation:none!important}}

