/* =============================================
CLUB SCHEDULER PRO -- Dark Theme
BRRStyle1.css (Global / Layout / Players)
============================================= */


:root {
--base-font-size: 1rem;
--app-ui-zoom: 1;
--player-font-size:1.1rem;

--bg:         #0f0f13;
--surface:    #1a1a22;
--surface2:   #22222e;
--surface3:   #2a2a38;
--border:     rgba(255,255,255,0.07);
--border2:    rgba(255,255,255,0.12);

--accent:     #6c63ff;
--accent-dim: rgba(108,99,255,0.15);
--accent-glow:rgba(108,99,255,0.40);
--accent2:    #ff6584;
--green:      #2dce89;
--green-dim:  rgba(45,206,137,0.15);
--amber:      #f59e0b;
--red:        #ef4444;

--text:       #f0f0f5;
--text-dim:   #a0a0c0;
--muted:      #6060a0;

--font-display: "Space Grotesk", sans-serif;
--font-body:    "DM Sans", -apple-system, BlinkMacSystemFont, sans-serif;

--r-sm: 10px;
--r-md: 14px;
--r-lg: 18px;
--r-xl: 24px;
--shadow: 0 4px 20px rgba(0,0,0,0.4);
--shadow-accent: 0 4px 20px var(--accent-glow);
}

/* Build 960 — keep player rating and delete controls readable on coloured player cards. */
body.tile-style-color #playersPage #playerList.player-list .player-edit-card .circle-btn.delete {
  background:rgba(15,23,42,.42) !important;
  border-color:rgba(255,255,255,.38) !important;
  color:#fff !important;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.14) !important;
}

/* Build 552 — sample-aligned Scheduling Mode carousel. */

#homeOrgGrid .org-scheduling-screen {
    margin:0 auto; padding:0 4px; box-sizing:border-box;
  color:#f8f7ff; font-family:var(--font-display,inherit);
}
.org-scheduling-heading { text-align:center; margin:3px 0 20px; }
.org-scheduling-heading h1 { margin:0; color:#fff; font-size:1.45rem; line-height:1.15; font-weight:850; letter-spacing:-.035em; }
.org-scheduling-heading p { margin:7px 0 0; color:#9896ad; font-family:var(--font-body,inherit); font-size:.72rem; }
.org-mode-carousel { position:relative; width:100%; }
.org-mode-viewport { width:100%; overflow:hidden; padding:0 4px; box-sizing:border-box; }
.org-mode-track { width:200%; display:flex; align-items:stretch; transform:translateX(0); transition:transform .35s cubic-bezier(.2,.8,.2,1); }
.org-mode-panel {
  width:50%; min-height:420px; padding:25px 22px 18px; box-sizing:border-box; position:relative;
  display:flex; flex-direction:column; border:1px solid rgba(144,76,255,.67); border-radius:20px;
  background:radial-gradient(circle at 9% 12%,rgba(109,48,221,.14),transparent 28%),linear-gradient(145deg,rgba(24,18,48,.97),rgba(12,14,27,.98));
  box-shadow:0 16px 36px rgba(0,0,0,.3),inset 0 1px 0 rgba(255,255,255,.025);
}
.org-mode-intro { min-height:104px; display:flex; align-items:center; gap:17px; }
.org-sample-mode-icon { width:68px; height:68px; flex:0 0 68px; display:grid; place-items:center; border-radius:50%; color:#e8e2ff; background:linear-gradient(145deg,#30205b,#201841); box-shadow:inset 0 0 0 1px rgba(152,102,255,.18); }
.org-sample-mode-icon svg { width:43px; height:43px; }
.org-rolling-icon { font-size:2.8rem; line-height:1; font-family:Arial,sans-serif; }
.org-sample-copy { display:flex; flex-direction:column; min-width:0; }
.org-sample-copy strong { color:#fff; font-size:1.05rem; line-height:1.15; }
.org-sample-copy em { margin-top:6px; color:#9c68ff; font-size:.72rem; line-height:1.2; font-style:normal; font-weight:650; }
.org-sample-copy span { margin-top:7px; color:#aaa8b8; font-family:var(--font-body,inherit); font-size:.69rem; line-height:1.5; }
.org-mode-options { min-height:93px; margin:22px -22px 0; padding:0 22px 19px; border-bottom:1px solid rgba(255,255,255,.06); box-sizing:border-box; }
.org-mode-options-spacer { min-height:115px; }
.org-control-label { margin:0 0 10px; color:#fff; font-size:.72rem; font-weight:750; }
.org-game-style { display:grid; grid-template-columns:1fr 1fr; border:1px solid rgba(255,255,255,.14); border-radius:12px; overflow:hidden; background:#121621; }
.org-game-style button { min-height:44px; border:0; border-right:1px solid rgba(255,255,255,.09); background:transparent; color:#b6b4c4; font:700 .75rem/1 var(--font-body,inherit); cursor:pointer; }
.org-game-style button:last-child { border-right:0; }
.org-game-style button span { margin-right:6px; color:#73798c; }
.org-game-style button.is-active { background:linear-gradient(135deg,#8644df,#6933c7); color:#fff; box-shadow:inset 0 0 0 1px rgba(255,255,255,.1); }
.org-game-style button.is-active span { color:#fff; }
.org-round-format { grid-template-columns:repeat(3,minmax(0,1fr)); }
.org-round-format button { padding:0 5px; }
.org-color-section + .org-color-section { margin-top:14px; }
.org-sample-winner-row { min-height:85px; display:grid; grid-template-columns:46px minmax(0,1fr) auto; align-items:center; gap:12px; }
.org-winner-icon { width:40px; height:40px; display:grid; place-items:center; border-radius:50%; color:#fff; font-size:1.15rem; background:#2d2154; }
.org-sample-winner-row strong { display:block; color:#fff; font-size:.75rem; line-height:1.1; }
.org-sample-winner-row small { display:block; margin-top:5px; color:#8e8b9f; font-family:var(--font-body,inherit); font-size:.64rem; line-height:1.45; }
.org-sample-winner-row .switch { transform:scale(.86); transform-origin:right center; }
.org-start-mode-btn { width:100%; min-height:56px; margin-top:auto; padding:0 17px; border:0; border-radius:14px; display:grid; grid-template-columns:38px minmax(0,1fr) 24px; align-items:center; gap:12px; background:linear-gradient(135deg,#9148f2,#7132cf); color:#fff; font:800 .86rem/1 var(--font-display,inherit); box-shadow:0 9px 22px rgba(111,48,206,.32),inset 0 1px 0 rgba(255,255,255,.14); cursor:pointer; transition:background .22s ease,box-shadow .22s ease,transform .16s ease; }
.org-start-mode-btn:active { transform:scale(.985); }
.org-start-mode-btn .org-start-play { width:34px; height:34px; margin:0; display:grid; place-items:center; border-radius:50%; background:#fff; color:#7936d8; font:800 .82rem/1 Arial,sans-serif; padding-left:2px; box-shadow:0 4px 12px rgba(25,12,58,.22); }
.org-start-mode-btn .org-start-label { min-width:0; margin:0; text-align:left; white-space:nowrap; font-size:.86rem; line-height:1; }
.org-start-mode-btn .org-start-arrow { margin:0; text-align:right; font:400 1.75rem/1 Arial,sans-serif; }
.org-start-mode-btn.is-continue { background:linear-gradient(135deg,#55d68f,#2eaa66); box-shadow:0 9px 22px rgba(37,176,103,.28),inset 0 1px 0 rgba(255,255,255,.18); }
.org-start-mode-btn.is-continue .org-start-play { color:#2cab68; }
.org-start-mode-btn:disabled { opacity:.43; cursor:not-allowed; transform:none; }
@media (max-width:380px) {
  .org-start-mode-btn { grid-template-columns:34px minmax(0,1fr) 20px; gap:9px; padding:0 13px; }
  .org-start-mode-btn .org-start-play { width:31px; height:31px; }
  .org-start-mode-btn .org-start-label { font-size:.79rem; }
}
.org-carousel-arrow { position:absolute; top:39%; z-index:4; width:36px; height:44px; padding:0; border:0; display:grid; place-items:center; border-radius:12px; background:linear-gradient(145deg,#7c3ee4,#5924bf); color:#fff; font:800 2rem/1 Arial,sans-serif; box-shadow:0 7px 16px rgba(68,27,146,.35); cursor:pointer; }
.org-carousel-prev { left:-12px; }
.org-carousel-next { right:-12px; }
.org-mode-carousel[data-active-slide="0"] .org-carousel-prev,
.org-mode-carousel[data-active-slide="2"] .org-carousel-next { opacity:.35; pointer-events:none; }
.org-carousel-dots { display:flex; justify-content:center; gap:10px; margin-top:18px; }
.org-carousel-dots button { width:10px; height:10px; padding:0; border:0; border-radius:50%; background:#474958; cursor:pointer; }
.org-carousel-dots button.is-active { background:#7548ff; box-shadow:0 0 0 3px rgba(117,72,255,.1); }
.org-swipe-hint { margin:11px 0 18px; color:#9a98a9; text-align:center; font:500 .66rem/1.2 var(--font-body,inherit); }
body.app-light .org-mode-panel { background:linear-gradient(145deg,#fff,#f4f1ff); color:#1b1730; }
body.app-light .org-scheduling-heading h1,
body.app-light .org-sample-copy strong,
body.app-light .org-control-label,
body.app-light .org-sample-winner-row strong { color:#1a1729; }
@media (max-width:380px) {
  .org-mode-panel { min-height:398px; padding:20px 18px 16px; }
  .org-mode-options { margin-left:-18px; margin-right:-18px; padding-left:18px; padding-right:18px; }
  .org-sample-mode-icon { width:60px; height:60px; flex-basis:60px; }
  .org-mode-intro { gap:13px; }
}

