/* ── LIGHT THEME OVERRIDE ── */
body.app-light {
  --bg:         #f4f6fb;
  --surface:    #ffffff;
  --surface2:   #eef1f7;
  --surface3:   #e2e7f0;
  --border:     rgba(0,0,0,0.08);
  --border2:    rgba(0,0,0,0.13);
  --card-bg:    #ffffff;

  --text:       #1a1a2e;
  --text-dim:   #555577;
  --muted:      #8888aa;

  --shadow:     0 4px 20px rgba(0,0,0,0.10);
  --shadow-accent: 0 4px 20px var(--accent-glow);
}
.lock-icon {
  
  
  
  
  
  border: 1.5px solid var(--border2, rgba(255,255,255,0.14));
  
  object-fit: contain;
  
  flex-shrink: 0;
  box-sizing: border-box;
}
.lock-icon:active {
  background: var(--surface3);
  border-color: var(--accent);
}
body.app-dark .lock-icon {
  filter: invert(1);
  background: rgba(255,255,255,0.07);
  border-color: rgba(255,255,255,0.16);
}

* { -webkit-tap-highlight-color: transparent; box-sizing: border-box; }
  html { font-size: var(--base-font-size); }
  html.lang-jp {
  /* Japanese glyphs render visually larger than Latin at the same rem size.
     Keep every app screen at a comparable visual height. */
  font-size: calc(var(--base-font-size) - .125rem);
  }
  body {
  margin: 0; padding: 0;
  font-family: var(--font-body);
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  /* Build 588 — whole-app display scaling, similar to browser page zoom. */
  zoom: var(--app-ui-zoom, 1);
  }
  body.lang-jp {
  line-height: 1.45;
  }

/* ── Top Bar ── */
.top-bar {
  display: flex;
  align-items: center;
  padding: 10px 14px;
  background: var(--bg);
  border-bottom: 1px solid var(--border);
  box-shadow: 0 2px 12px rgba(0,0,0,0.06);
  position: relative;
  z-index: 10;
}
.app-logo-premium {
  position: absolute; left: 50%; transform: translateX(-50%);
  font-family: var(--font-display);
  font-size: 1.125rem; font-weight: 700; letter-spacing: 0.3px;
  color: var(--text); white-space: nowrap; pointer-events: none;
  display: flex; align-items: center; gap: 6px;
}
.app-logo-premium::before {
  content: "🏸";
  font-size: 1rem;
}
.menu-btn { font-size: 1.3rem; cursor: pointer; user-select: none; color: var(--text-dim); padding: 4px; border-radius: 8px; }

.lang-wrapper { margin-right: auto; position: relative; }
.lang-btn {
  width: 36px; height: 36px; border-radius: 10px;
  border: 1px solid var(--border2);
  background: var(--surface2);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.25rem; cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}
