.player-mgmt-toolbar {
  display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 12px;
}
.player-mgmt-add-btn {
  padding: 7px 14px; border-radius: var(--r-sm);
  border: none; background: var(--accent);
  color: #fff; font-size: 0.85rem; font-weight: 700; cursor: pointer;
}
.player-mgmt-pwd-btn {
  padding: 7px 14px; border-radius: var(--r-sm);
  border: 1px solid var(--border2); background: var(--surface3);
  color: var(--text); font-size: 0.85rem; cursor: pointer;
}

.player-mgmt-list {
  display: flex; flex-direction: column; gap: 6px;
}
.player-mgmt-empty {
  font-size: 0.85rem; color: var(--muted); text-align: center; padding: 16px 0;
}
.player-mgmt-row {
  display: flex; align-items: center; gap: 10px;
  padding: 0 12px; height: 44px;
  border-radius: var(--r-xl);
  border: 1px solid var(--border2);
  background: var(--surface2);
  box-sizing: border-box;
}
.player-mgmt-avatar {
  width: 28px; height: 28px; border-radius: 50%;
  cursor: pointer; flex-shrink: 0;
  transition: transform 0.15s;
}
.player-mgmt-avatar:hover { transform: scale(1.15); }
.player-mgmt-name {
  flex: 1; font-size: 0.88rem; color: var(--text);
