  color: var(--muted); transition: color 0.2s; flex-shrink: 0;
}
.player-mgmt-del-btn:hover { color: var(--red); }

/* === ADD PLAYERS BROWSE TAB === */
.addplayers-subtabs { margin-bottom: 8px; }

.addplayers-browse-list {
  margin-top: 8px;
  max-height: 280px;
  overflow-y: auto;
}

.browse-player-row {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 4px;
  border-bottom: 1px solid var(--border, #eee);
}

.browse-player-gender {
  width: 22px;
  height: 22px;
  object-fit: contain;
}

.browse-player-name {
  flex: 1;
  font-size: 0.82rem;
}

.browse-player-btn {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: none;
  font-size: 1.2rem;
  line-height: 1;
  cursor: pointer;
  font-weight: bold;
  display: flex;
  align-items: center;
  justify-content: center;
}

.browse-player-btn-add {
  background: #2dce89;
  color: #fff;
}

.browse-player-btn-add:hover { background: #24b577; }

.browse-player-btn-remove {
  background: #f5365c;
  color: #fff;
}

.browse-player-btn-remove:hover { background: #d42b50; }

/* ── Player subtabs (All / Playing) ── */
.player-subtab-bar {
  display: flex;
  gap: 8px;
  margin-bottom: 12px;
  border-bottom: 2px solid var(--border, #e0e0e0);
  padding-bottom: 0;
}
.player-subtab-btn {
  background: none;
  border: none;
  padding: 6px 16px;
  font-size: 0.9rem;
  color: var(--muted, #888);
  cursor: pointer;
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
  font-weight: 500;
}
.player-subtab-btn.active {
  color: var(--accent, #5e72e4);
  border-bottom-color: var(--accent, #5e72e4);
}

/* ── ⚡ Vault Tab ── */
.vault-tab-btn {
  color: var(--amber) !important;
}
.vault-tab-btn.active {
  color: var(--amber) !important;
  border-bottom-color: var(--amber) !important;
}
.vault-status-strip {
  display: flex; align-items: center; gap: 8px;
  background: rgba(45,206,137,0.08);
  border: 1px solid rgba(45,206,137,0.15);
  border-radius: var(--r-lg); padding: 8px 12px;
  margin-bottom: 12px;
}
.vault-status-dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--muted); flex-shrink: 0;
}
.vault-status-name { font-size: 0.88rem; font-weight: 600; flex: 1; }
.vault-status-role {
  font-size: 0.6rem; font-weight: 700;
  border-radius: 10px; padding: 2px 8px;
  display: none;
}
.vault-logout-btn {
  padding: 5px 12px; border-radius: 20px; border: none;
  background: rgba(239,68,68,0.12); color: var(--red);
  font-size: 0.75rem; font-weight: 700; cursor: pointer;
  font-family: var(--font-body);
}
.vault-inner-tabs {
  display: flex; gap: 4px;
  background: var(--surface3);
  border-radius: var(--r-xl); padding: 4px;
  margin-bottom: 12px;
}
.vault-inner-tab {
  flex: 1; border: none; background: none;
  padding: 7px 4px; border-radius: var(--r-lg);
  font-size: 0.78rem; font-weight: 600;
  color: var(--muted); cursor: pointer;
  transition: all 0.15s; font-family: var(--font-body);
}
.vault-inner-tab.active {
  background: var(--amber);
  color: #000;
  box-shadow: 0 2px 8px rgba(245,158,11,0.3);
}
.vault-inner-content { display: none; }
.vault-inner-content.active { display: block; }

/* ── Club Join Overlay ── */
.club-join-overlay {
  position: fixed; inset: 0; z-index: 1000;
  background: var(--bg);
  display: flex; align-items: center; justify-content: center;
  padding: 24px;
}
.club-join-card {
  background: var(--surface2);
  border: 1px solid var(--border2);
  border-radius: var(--r-xl);
  padding: 28px 24px;
  width: 100%; max-width: 360px;
  box-shadow: var(--shadow);
}
.club-join-logo {
  font-family: var(--font-display);
  font-size: 1.2rem; font-weight: 700;
  color: var(--accent); text-align: center;
  margin-bottom: 6px;
}
.club-join-title {
  font-size: 0.85rem; color: var(--muted);
  text-align: center; margin-bottom: 20px;
}
.club-join-select {
  width: 100%; margin-bottom: 10px;
}
.club-join-input {
  width: 100%; margin-bottom: 10px;
}
.club-join-btn {
  width: 100%; padding: 11px;
  border-radius: var(--r-xl); border: none;
  background: var(--accent); color: #fff;
  font-size: 0.9rem; font-weight: 700;
  cursor: pointer; font-family: var(--font-body);
}

/* ── Club Management toggle in Settings ── */
.club-mgmt-toggle {
  width: 100%; padding: 13px 16px;
  background: none; border: none;
  color: var(--text-dim); font-size: 0.88rem; font-weight: 600;
  cursor: pointer; text-align: left;
  font-family: var(--font-body);
  display: flex; align-items: center; justify-content: space-between;
  transition: color 0.15s;
}
.club-mgmt-toggle:hover { color: var(--text); }


/* ── Vault Tiles (Option B -- Dark Glass) ── */
.vault-tile-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  padding: 6px 0;
  margin: 0 16px;
}
.vault-tile {
  border-radius: 20px;
  padding: 16px;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 5px;
  background: var(--surface);
  border: 1.5px solid rgba(255,255,255,0.13);
  box-shadow: 0 2px 12px rgba(0,0,0,0.18), inset 0 1px 0 rgba(255,255,255,0.08);
  transition: transform 0.15s, background 0.15s;
  -webkit-tap-highlight-color: transparent;
}
.vault-tile::before {
  content: "";
  position: absolute; top: 0; left: 0; right: 0; height: 3px;
  border-radius: 18px 18px 0 0;
}
.vault-tile:active { transform: scale(0.97); background: var(--surface2); }

/* Coloured top borders -- glow mode only */


/* Flat mode -- light theme vault tiles */
body.app-light .vault-tile {
  background: var(--surface);
  border-color: var(--border);
  box-shadow: 0 2px 8px rgba(0,0,0,0.06);
}
body.app-light .vt-stat { color: var(--text); }
body.app-light .vt-name { color: var(--text); }
body.app-light .vt-sub  { color: var(--muted); }

.vt-club {
  min-height: unset;
  flex-direction: row;
  align-items: center;
  gap: 16px;
  justify-content: flex-start;
  padding: 18px 20px;
}

.vt-badge {
  position: absolute;
  top: 10px; right: 10px;
  border-radius: 20px;
  padding: 2px 8px;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.05em;
}
.vt-playing  .vt-badge { background: rgba(245,166,35,0.18); color: #f5a623; }
.vt-requests .vt-badge { background: rgba(230,55,87,0.18);  color: #e63757; }

.vt-icon {
  width: 44px; height: 44px;
  min-width: 44px;
  border-radius: 11px;
  background: var(--surface2);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.4rem;
  margin-bottom: 4px;
  flex-shrink: 0;
}

/* ── Slots tile: full-width, top priority, mini calendar preview ── */
.vt-slots {
  grid-column: 1 / -1;
  flex-direction: column;
  gap: 10px;
}
.vt-slots .vt-icon { margin-bottom: 0; }
.vt-slots-header {
  display: flex;
  align-items: center;
  gap: 12px;
}


.vt-slots-cal-nav { padding-top: 6px; }
.vt-slots-cal-month-label {
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--text-dim);
  text-align: center;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.vt-slots-cal-weekdays {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  font-size: 0.58rem;
  color: var(--muted);
  text-align: center;
  margin-top: 4px;
}
.vt-slots-cal-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 2px;
  margin-top: 2px;
}
.vt-slots-cal-day {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  aspect-ratio: 1;
  font-size: 0.66rem;
  color: var(--text);
  border-radius: 6px;
}
.vt-slots-cal-day.vt-slots-cal-empty { visibility: hidden; }
.vt-slots-cal-day.vt-slots-cal-past { opacity: 0.4; }
.vt-slots-cal-day.vt-slots-cal-today {
  background: rgba(74,158,255,0.18);
  color: var(--text);
  font-weight: 700;
}
.vt-slots-cal-dot {
  width: 4px; height: 4px;
  border-radius: 50%;
  display: block;
}
.vt-slots-cal-dot.vs-dot-upcoming  { background: #2dce89; }
.vt-slots-cal-dot.vs-dot-completed { background: #4a9eff; }
.vt-text {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.vt-stat {
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 700;
  color: var(--text);
  line-height: 1.2;
}
.vt-name {
  font-size: 0.78rem;
  color: var(--muted);
}
.vt-sub {
  font-size: 0.72rem;
  color: var(--muted);
  opacity: 0.7;
}

/* ── Vault Club Status Tile ── */
.vault-club-tile {
  display: flex;
  align-items: center;
  gap: 12px;
  border-radius: 18px;
  padding: 16px 18px;
  margin: 6px 16px 0;
  position: relative;
  overflow: hidden;
  cursor: default;
}
.vault-club-tile::before {
  content: "";
  position: absolute; top: 0; left: 0; right: 0; height: 3px;
  background: #e63757;
  border-radius: 18px 18px 0 0;
}

/* Dark mode */
body:not(.app-light) .vault-club-tile {
  background: var(--surface2, #1a1a2e);
  border: 1px solid var(--border, #2a2a40);
  box-shadow: 0 0 14px rgba(230,55,87,0.15);
}
body:not(.app-light) .vault-club-tile::before {
  box-shadow: 0 0 14px rgba(230,55,87,0.8);
}
body:not(.app-light) .vct-name { color: #fff; }
body:not(.app-light) .vct-change-btn { background: rgba(255,255,255,0.08); color: #aaa; border: 1px solid #2a2a40; }

/* Light mode */
body.app-light .vault-club-tile {
  background: #fff0f2;
  border: 1.5px solid #ffd0d8;
  box-shadow: 0 2px 12px rgba(230,55,87,0.08);
}
body.app-light .vct-name { color: #1a1a2e; }
body.app-light .vct-change-btn { background: #ffe8ec; color: #c0392b; border: none; }

.vct-dot {
  width: 10px; height: 10px; border-radius: 50%;
  background: #2dce89; flex-shrink: 0;
  box-shadow: 0 0 0 3px rgba(45,206,137,0.2);
}
.vct-info { flex: 1; }
.vct-name { font-size: 1rem; font-weight: 800; }
.vct-badge {
  display: inline-block;
  font-size: 0.65rem; font-weight: 800;
  padding: 2px 8px; border-radius: 6px;
  background: #2dce89; color: #000;
  margin-top: 4px; letter-spacing: 0.05em;
}
.vct-change-btn {
  border: none; border-radius: 10px;
  padding: 8px 16px; font-size: 0.82rem; font-weight: 600;
  cursor: pointer; white-space: nowrap; flex-shrink: 0;
}

/* ── Organiser club tile -- blue accent, not red ── */
.org-club-tile::before { background: #6c8cff !important; }
body:not(.app-light) .org-club-tile {
  box-shadow: 0 0 14px rgba(108,140,255,0.12) !important;
}
body:not(.app-light) .org-club-tile::before {
  box-shadow: 0 0 14px rgba(108,140,255,0.6) !important;
}
body.app-light .org-club-tile {
  background: #f0f2ff !important;
  border-color: #cdd5ff !important;
  box-shadow: 0 2px 12px rgba(108,140,255,0.08) !important;
}
.org-badge {
  background: rgba(108,140,255,0.18) !important;
  color: #6c8cff !important;
}

/* ── Rounds Page -- Single Tight Top Bar ── */
.rounds-top-bar {
  display: flex;
  align-items: center;
  height: 54px;
  padding: 0 14px;
  gap: 2px;
  /* Light mode: clean white surface with subtle shadow */
  background: #ffffff;
  border-bottom: 1px solid #e0e4ed;
  box-shadow: 0 1px 4px rgba(0,0,0,0.07);
}
body.app-dark .rounds-top-bar {
  /* Dark mode: elevated surface, clearly above page bg */
  background: #1e2030;
  border-bottom: 1px solid #2a2d3e;
  box-shadow: 0 1px 6px rgba(0,0,0,0.35);
}
.rtb-back {
  color: var(--accent, #6c8cff);
  font-size: 0.82rem;
  font-weight: 700;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
}
.rtb-settings {
  background: var(--surface2, rgba(255,255,255,0.08));
  border: 1.5px solid var(--border2, rgba(255,255,255,0.12));
  cursor: pointer;
  font-size: 1.25rem;
  padding: 0;
  width: 38px;
  height: 38px;
  border-radius: 10px;
  color: var(--text);
  transition: background 0.15s, border-color 0.15s;
  margin-left: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
body.app-dark .rtb-settings {
  background: rgba(255,255,255,0.07);
  border-color: rgba(255,255,255,0.14);
}
.rtb-settings:active {
  background: var(--surface3, rgba(255,255,255,0.15));
  border-color: var(--accent, #6c8cff);
}
.rtb-spacer { flex: 1; }
.rtb-live {
  display: flex;
  align-items: center;
  gap: 5px;
  /* Solid pill background — clearly visible in both modes */
  background: rgba(45,206,137,0.15);
  border: 1px solid rgba(45,206,137,0.35);
  border-radius: 20px;
  padding: 2px 8px 2px 6px;
}
body.app-dark .rtb-live {
  background: rgba(45,206,137,0.12);
  border-color: rgba(45,206,137,0.3);
}
.rtb-dot {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: #2dce89;
  box-shadow: 0 0 5px #2dce89;
  animation: rtbPulse 1.5s infinite;
  flex-shrink: 0;
}
.rtb-live-txt {
  font-size: 0.65rem;
  font-weight: 700;
  color: #1aab70;
  letter-spacing: 0.05em;
}
body.app-dark .rtb-live-txt {
  color: #2dce89;
}
.rtb-end {
  /* Solid red pill — always clearly readable */
  background: #e63757;
  border: none;
  color: #ffffff;
  border-radius: 5px;
  padding: 3px 10px;
  font-size: 0.65rem;
  font-weight: 700;
  cursor: pointer;
  margin-left: 8px;
  transition: filter 0.15s;
}
.rtb-end:active { filter: brightness(0.88); }
@keyframes rtbPulse {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0.3; }
}

/* ── Dashboard Force End Button ── */
.dash-card-footer {
  margin-top: 10px;
  padding-top: 10px;
  border-top: 1px solid var(--border, #2a2a40);
}
.dash-force-end-btn {
  width: 100%;
  padding: 8px;
  background: rgba(230,55,87,0.08);
  border: 1px solid rgba(230,55,87,0.25);
  color: #e63757;
  border-radius: 8px;
  font-size: 0.78rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s;
}
.dash-force-end-btn:active {
  background: rgba(230,55,87,0.18);
}
.dash-force-end-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* ── My Card Period Stats -- Style C ── */
.mc-period-list {
  background: var(--surface, #fff);
  border: 1px solid var(--border, #eee);
  border-radius: 12px;
  overflow: hidden;
  margin: 8px 16px 12px;
}
.mc-period-row {
  display: flex;
  align-items: center;
  padding: 9px 14px;
  border-bottom: 1px solid var(--border, #f5f5f5);
}
.mc-period-row:last-child { border-bottom: none; }
.mc-period-label {
  flex: 1;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--muted, #888);
}
.mc-period-stats-inner {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.68rem;
  color: var(--muted, #aaa);
  font-weight: 600;
}
.mc-period-val {
  font-size: 0.9rem;
  font-weight: 800;
  line-height: 1;
}
.mc-period-val.wins   { color: #2dce89; }
.mc-period-val.losses { color: #e63757; }
.mc-period-val.points {
  font-size: 0.75rem;
  font-weight: 700;
  color: #f5a623;
  background: rgba(245,166,35,0.1);
  padding: 1px 6px;
  border-radius: 10px;
}
.mc-period-val.cost {
  font-size: 0.75rem;
  font-weight: 700;
  color: #6c8cff;
  background: rgba(108,140,255,0.1);
  padding: 1px 6px;
  border-radius: 10px;
}

/* ── My Card Session Rows ── */
.mc-session-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 0;
  border-bottom: 1px solid var(--border, #eee);
  font-size: 0.82rem;
}
.mc-session-date {
  flex: 1;
  color: var(--muted, #888);
  font-weight: 600;
  font-size: 0.78rem;
}
.mc-session-stat {
  font-weight: 700;
  font-size: 0.78rem;
  padding: 2px 6px;
  border-radius: 6px;
}
.mc-session-stat.wins   { color: #2dce89; background: rgba(45,206,137,0.1); }
.mc-session-stat.losses { color: #e63757; background: rgba(230,55,87,0.1); }
.mc-session-stat.points { color: #f5a623; background: rgba(245,166,35,0.1); }

/* ── Shuttle Cost Sheet ── */
.shuttle-sheet {
  
  
  
  width: 100%;
  box-shadow: 0 -4px 30px rgba(0,0,0,0.35);
}


.shuttle-handle {
  width: 2.4rem; height: 0.22rem;
  background: var(--border, #ddd); border-radius: 0.2rem;
  margin: 0 auto 0.8rem;
  opacity: 0.5;
}
.shuttle-title {
  font-size: 1rem; font-weight: 800;
  color: var(--text, #fff); margin-bottom: 0.75rem;
  display: flex; align-items: center; gap: 0.4rem;
  letter-spacing: 0.01em;
}
.shuttle-mode-toggle {
  display: flex; 
    
  
}

.shuttle-mode-btn {
  flex: 1; text-align: center; 
    font-weight: 700;
   cursor: pointer; border: none; background: none;
  font-family: inherit; transition: background 0.15s, color 0.15s;
}
.shuttle-mode-btn.active {
  background: var(--accent, #6c63ff); 
  
}
body.app-light .shuttle-mode-btn.active { background: #6c63ff;  box-shadow: 0 1px 6px rgba(108,99,255,0.25); }
.shuttle-2col { display: flex; gap: 0.55rem; margin-bottom: 0.5rem; }
.shuttle-input-group { flex: 1; margin-bottom: 0.55rem; }
.shuttle-input-label {
   font-weight: 700;
    display: flex;
  align-items: center; gap: 0.25rem; letter-spacing: 0.02em;
}
.shuttle-input {
  width: 100%; 
   
  font-size: 0.95rem; font-weight: 600;
   
  font-family: inherit; box-sizing: border-box;
  transition: border-color 0.15s;
}
.shuttle-input::placeholder {
  color: var(--muted, #555);
  font-weight: 400;
  font-size: 0.82rem;
  opacity: 0.6;
