.jc-club-cancel-request-btn {
  min-height: 28px;
  padding: 4px 9px;
  border: 1px solid rgba(239,68,68,.48);
  border-radius: 999px;
  background: rgba(239,68,68,.10);
  color: #fb7185;
  font-size: .61rem;
  font-weight: 800;
  cursor: pointer;
}
.jc-club-cancel-request-btn:active { transform: scale(.96); }
.jc-club-cancel-request-btn:disabled { opacity: .55; cursor: wait; }
.jc-nickname-choices {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 12px;
}
.jc-nickname-group-title {
  flex-basis: 100%;
  color: var(--muted);
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.jc-nickname-group-title:not(:first-child) { margin-top: 5px; }
.jc-nickname-pill {
  min-height: 38px;
  padding: 8px 13px;
