/* ═══════════════════════════════════════════
   MODE LAUNCHER -- Full Screen
═══════════════════════════════════════════ */
/* ══════════════════════════════════════════════════════════
   HOME PAGE — Card-style mode launcher (matches screenshot)
   Viewer=purple  Organiser=green  Vault=orange
══════════════════════════════════════════════════════════ */

.mode-launcher-fullscreen {
  position: fixed;
  inset: 0;
  z-index: 9999;
  background: var(--bg, #0d0d1a);
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-start;
  animation: mlFadeIn 0.2s ease;
}
@keyframes mlFadeIn { from { opacity: 0; } to { opacity: 1; } }

/* ── Topbar ── */
.ml-topbar-home {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  padding: 14px 18px 14px !important;
  padding-top: max(14px, env(safe-area-inset-top, 14px)) !important;
  background: var(--surface, #161625) !important;
  border-bottom: 1px solid var(--border, #2a2a40) !important;
}
.ml-topbar-approw {
  display: flex;
  align-items: center;
  gap: 12px;
}
.ml-topbar-appicon {
  font-size: 2rem;
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1a3320;
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,0.08);
}
.ml-topbar-appname {
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--text, #fff);
  line-height: 1.2;
}
.ml-topbar-username {
  font-size: 0.72rem;
  color: var(--muted, #888);
  margin-top: 2px;
}
.ml-topbar-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* ── Scroll inner ── */
.ml-inner {
  flex: 1;
  width: 100%;
  max-width: 480px;
  padding: 24px 18px env(safe-area-inset-bottom, 28px);
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-start;
  align-self: center;
  overflow-y: auto;
}

/* ── Section labels ── */
.ml-modes { width: 100%; display: flex; flex-direction: column; gap: 14px; margin-bottom: 24px; }

.ml-section-label {
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent, #6c8cff);
  padding: 0 4px;
  margin-top: 20px;
  margin-bottom: 2px;
  display: flex;
  align-items: center;
  gap: 7px;
}
.ml-section-label::after {
  content: "";
  flex: 1;
  height: 1px;
  background: currentColor;
  opacity: 0.2;
}
.ml-section-icon { font-size: 0.88rem; }
.ml-section-first { margin-top: 0; }

/* ── Mode cards ── */
.ml-mode {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 20px 18px;
  border-radius: 20px;
  border: none;
  cursor: pointer;
  width: 100%;
  text-align: left;
  position: relative;
  overflow: hidden;
  transition: transform 0.13s, box-shadow 0.13s;
  box-shadow: 0 4px 24px rgba(0,0,0,0.3);
}
.ml-mode:active { transform: scale(0.975); }

