  display: inline-block;
}



.export-vs {
  width: 10%;
  text-align: center;
  
}

/* Sitting out */
.export-rest-title {
  margin: 5px;
  font-weight: 600;
}

.export-rest-box {
  margin: 5px;
  font-size: .8125rem;
}

/* ===== PLAYER BUTTON OVERRIDES (FINAL) ===== */


/* ─────────────────────────────────────────────
   PROFILE BUTTON (header)
───────────────────────────────────────────── */
.profile-btn {
  background: var(--surface2);
  border: 1px solid var(--border2);
  cursor: pointer;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 10px;
  transition: background 0.15s, border-color 0.15s;
}
.profile-btn:hover { background: var(--surface3); border-color: var(--accent); }
.profile-btn-avatar {
  width: 28px;
  height: 28px;
  border-radius: 6px;
  object-fit: cover;
  border: 2px solid var(--accent);
}
.profile-btn-icon { font-size: 1.125rem; }

/* ─────────────────────────────────────────────
   PROFILE OVERLAY + DRAWER
───────────────────────────────────────────── */
.profile-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.45);
  z-index: 600;
  transition: opacity 0.25s;
}
.profile-overlay.hidden { display: none; }

.profile-drawer {
  position: fixed;
  bottom: 0; left: 0; right: 0;
  background: var(--surface);
  border-radius: 20px 20px 0 0;
  box-shadow: 0 -8px 40px rgba(0,0,0,0.25);
  z-index: 601;
  padding: 0 0 32px;
  max-height: 88vh;
  overflow-y: auto;
  transform: translateY(100%);
  transition: transform 0.32s cubic-bezier(0.32,0.72,0,1);
}
.profile-drawer.open { transform: translateY(0); }

/* ── Drawer header ── */
.profile-drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px 10px;
  border-bottom: 1px solid var(--border);
}
.profile-drawer-title {
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 800;
  color: var(--text);
  letter-spacing: 0.5px;
}
.profile-drawer-close {
  background: rgba(230, 55, 87, 0.10);
  border: 2px solid rgba(230, 55, 87, 0.7);
  border-radius: 50%;
  width: 28px; height: 28px;
  font-size: 0.8rem;
  font-weight: 700;
  color: #e63757;
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  transition: background 0.15s;
}
.profile-drawer-close:active { background: rgba(230, 55, 87, 0.22); }

/* ─────────────────────────────────────────────
   PLAYER PICKER
───────────────────────────────────────────── */
.profile-picker-hint {
  font-size: 0.82rem;
  color: var(--text-dim);
  padding: 10px 20px 6px;
}
.profile-picker-list {
  display: flex;
  flex-direction: column;
  padding: 6px 12px;
  gap: 4px;
  max-height: 60vh;
  overflow-y: auto;
}
.profile-picker-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 12px;
  background: var(--surface2);
  border: 1px solid var(--border);
  font-family: var(--font-display);
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  text-align: left;
  transition: background 0.15s;
}
.profile-picker-item:hover { background: var(--surface3); }
.profile-picker-avatar {
  width: 32px; height: 32px;
