/* ── Appearance Panel Enhancements ── */
.appear-pill-group { transition: all 0.2s; }

@keyframes appearPulse {
  0%   { transform: scale(1); }
  40%  { transform: scale(1.12); box-shadow: 0 0 0 6px var(--accent-glow); }
  100% { transform: scale(1); }
}
