}
@keyframes applySuccess {
  0%   { transform: scale(1.02); }
  50%  { transform: scale(1.08); background: var(--green); border-color: var(--green); box-shadow: 0 6px 20px rgba(45,206,137,0.5); }
  100% { transform: scale(1); }
}
.appear-apply-btn.appear-apply-success {
  animation: applySuccess 0.5s ease forwards;
}

