/* ═══════════════════════════════════════════
   SCS iOS-STYLE PAGE HEADER
   Layout: [✕]  [icon | title / sub]  [🌙][⏻]
═══════════════════════════════════════════ */
.scs-topbar {
  display: flex;
  align-items: center;
  padding: 10px 14px;
  gap: 10px;
  background: var(--surface, #16162a);
  border-bottom: 1px solid var(--border, rgba(255,255,255,0.07));
  position: sticky;
  top: 0;
  z-index: 30;
  flex-shrink: 0;
}

/* Standalone variant (mode select overlay — not sticky) */
.scs-topbar-standalone {
  position: relative;
  top: auto;
  border-bottom: 1px solid var(--border, rgba(255,255,255,0.07));
  background: var(--bg, #0d0d1a);
  flex-shrink: 0;
}

/* Page variant — same as default */
.scs-topbar-page {
  position: sticky;
}

/* ── ✕ close button (left) ── */
.scs-topbar-x {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 2px solid rgba(230, 55, 87, 0.7);
  background: rgba(230, 55, 87, 0.10);
  color: #e63757;
  font-size: 0.85rem;
  font-weight: 700;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: background 0.15s, border-color 0.15s;
}
.scs-topbar-x:active {
  background: rgba(230, 55, 87, 0.22);
  border-color: #e63757;
}

/* ── Centre block (icon + title/sub) ── */
.scs-topbar-center {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  cursor: pointer;
}

.scs-topbar-icon-wrap {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: var(--accent, #6c8cff);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  flex-shrink: 0;
}

.scs-topbar-text {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.scs-topbar-title {
  font-family: var(--font-display, inherit);
  font-size: 0.95rem;
  font-weight: 800;
  color: var(--text, #fff);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.scs-topbar-sub {
  font-size: 0.72rem;
  color: var(--text-dim, #888);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ── Right buttons group ── */
.scs-topbar-right {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.scs-topbar-btn {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1px solid var(--border, rgba(255,255,255,0.1));
  background: var(--surface2, rgba(255,255,255,0.07));
  color: var(--text-dim, #888);
  font-size: 1rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s, color 0.15s;
  flex-shrink: 0;
}
.scs-topbar-btn:active {
  background: var(--surface3, rgba(255,255,255,0.14));
}

/* Power button — red tint */
.scs-topbar-power {
  color: #e63757;
  border-color: rgba(230,55,87,0.3);
  background: rgba(230,55,87,0.08);
}
.scs-topbar-power:active {
  background: rgba(230,55,87,0.18);
}

/* ── Light theme overrides ── */
body.app-light .scs-topbar {
  background: #ffffff;
  border-bottom-color: #e8e8f0;
}
body.app-light .scs-topbar-standalone {
  background: #f5f5fb;
  border-bottom-color: #e8e8f0;
}
body.app-light .scs-topbar-x {
  background: rgba(230, 55, 87, 0.08);
  border-color: rgba(230, 55, 87, 0.6);
  color: #c0392b;
}
body.app-light .scs-topbar-title {
  color: #1a1a2e;
}
body.app-light .scs-topbar-sub {
  color: #999;
}
body.app-light .scs-topbar-btn {
  background: #f2f2f7;
  border-color: #e0e0ea;
  color: #555;
}
body.app-light .scs-topbar-power {
  color: #e63757;
  border-color: rgba(230,55,87,0.3);
  background: rgba(230,55,87,0.06);
}

/* Icon background per mode */
body .scs-topbar-icon-wrap { background: var(--scs-icon-bg, rgba(108,140,255,0.18)); }
body.viewer-mode  .scs-topbar-icon-wrap { background: rgba(108,140,255,0.18); }
body.organiser-mode .scs-topbar-icon-wrap { background: rgba(45,206,137,0.18); }
body.vault-mode   .scs-topbar-icon-wrap { background: rgba(245,166,35,0.18); }

