.auth-btn-demo:active { transform: scale(0.98); }
body.app-light .auth-btn-demo {
  background: linear-gradient(135deg, #ede9fe, #ddd6fe);
  border-color: rgba(139,92,246,0.3);
  color: #6d28d9;
}

/* LINE Login — official green identity with consistent auth geometry. */
.auth-welcome-brand {
  width: 100%;
  margin: 14px 0 48px;
  text-align: center;
}
.auth-welcome-brand h1 {
  margin: 0;
  color: var(--text);
  font-family: var(--font-body);
  font-size: clamp(2rem, 10vw, 2.75rem);
  font-weight: 820;
  line-height: 1.08;
  letter-spacing: -.035em;
  white-space: nowrap;
}
.auth-welcome-brand p {
  max-width: 360px;
  margin: 20px auto 0;
  color: var(--muted);
  font-size: clamp(.94rem, 4.2vw, 1.08rem);
  line-height: 1.55;
}

.auth-btn-line {
  width: 100%;
  min-height: 50px;
  padding: 11px 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 1px solid #05b94e;
  border-radius: 14px;
  background: #06c755;
  color: #fff;
  font-family: var(--font-body);
  font-size: .96rem;
  font-weight: 800;
  cursor: pointer;
  box-shadow: 0 8px 18px rgba(6, 199, 85, .20);
  transition: transform .15s ease, filter .15s ease, opacity .15s ease;
}
.auth-btn-line:hover { filter: brightness(1.04); }
.auth-btn-line:active { transform: scale(.985); }
.auth-btn-line:disabled { cursor: wait; opacity: .68; }
.auth-btn-line.is-loading { filter: saturate(.72); }
.auth-line-mark {
  min-width: 35px;
  height: 24px;
  padding: 0 5px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 7px;
  background: #fff;
  color: #06a947;
  font-size: .60rem;
  font-weight: 950;
  letter-spacing: -.03em;
  line-height: 1;
}
.auth-provider-divider {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--muted);
  font-size: .75rem;
  text-align: center;
}
.auth-provider-divider::before,
.auth-provider-divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--border);
}
.auth-social-account-note {
  margin: -2px 8px 2px;
  color: var(--muted);
  font-size: .76rem;
  line-height: 1.45;
  text-align: center;
}
.auth-btn-other {
  min-height: 50px;
  display: grid;
  grid-template-columns: 24px 1fr 24px;
  align-items: center;
  gap: 8px;
  text-align: center;
}
.auth-other-methods {
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: 14px;
  background: var(--surface);
  text-align: left;
}
.auth-other-methods[hidden] {
  display: none !important;
}
.auth-other-methods-title {
  color: var(--text);
  font-size: .92rem;
  font-weight: 800;
}
.auth-other-methods-copy {
  margin-top: 4px;
  color: var(--muted);
  font-size: .76rem;
  line-height: 1.4;
}
.auth-other-methods-actions {
  display: grid;
  grid-template-columns: 1fr;
  gap: 9px;
  margin-top: 14px;
