/* Demo banner */
#demoBanner {
  position: sticky; top: 0; z-index: 999;
  background: linear-gradient(90deg, #1e0a3c, #2d1b69);
  border-bottom: 1px solid rgba(139,92,246,0.3);
}
.demo-banner-inner {
