/* ── Sliding segmented control (Session Mode / Gender / Rating / Visibility) ── */
.vs-segmented {
  position: relative;
  display: flex;
  background: rgba(0,0,0,0.28);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 16px;
  padding: 4px;
  gap: 2px;
}
.vs-segmented-thumb {
  position: absolute;
  top: 4px;
  bottom: 4px;
  left: 4px;
  width: 0;
  border-radius: 12px;
  background: linear-gradient(135deg, #4a9eff, #704bff);
  box-shadow: 0 6px 16px rgba(74,158,255,0.35);
  transition: left 0.25s cubic-bezier(0.4,0,0.2,1), width 0.25s cubic-bezier(0.4,0,0.2,1);
  z-index: 0;
}
.vs-segmented .vs-pill {
  position: relative;
  z-index: 1;
  flex: 1;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  color: #a8a2cf;
  white-space: nowrap;
  padding: 10px 8px;
  min-height: 0;
  transition: color 0.2s;
}
.vs-segmented .vs-pill.vs-pill-active {
  color: #fff !important;
  background: transparent !important;
  box-shadow: none !important;
}
.vs-segmented .vs-pill:active { transform: none; }
.vs-segmented-visibility .vs-pill { font-size: 0.9rem; }

