}
.scs-quick-slot-title {
  flex: 1;
  text-align: center;
  font-family: var(--font-display, inherit);
  font-weight: 800;
  font-size: 1rem;
  color: var(--text, #f0f0f5);
}
.scs-quick-slot-spacer {
  width: 78px;
  flex-shrink: 0;
}
.scs-quick-slot-body {
  flex: 1;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  padding: 16px 14px calc(28px + env(safe-area-inset-bottom, 0px));
}
.scs-quick-slot-card-wrap {
  width: 100%;
  max-width: 520px;
  margin: 0 auto;
}
.scs-quick-slot-card-wrap .mc-slot-card {
  margin: 0 auto;
}
.scs-quick-slot-card-wrap .mc-slot-card-head {
  cursor: default;
}
.scs-quick-slot-loading,
.scs-quick-slot-empty {
  max-width: 520px;
  margin: 28px auto;
  padding: 18px;
  border-radius: 18px;
  background: var(--surface, #1a1a22);
  border: 1px solid var(--border, rgba(255,255,255,0.08));
  color: var(--text-dim, #a0a0c0);
  text-align: center;
  font-weight: 700;
}
body.app-light .scs-quick-slot-page {
  background: var(--bg, #f4f6fb);
  color: var(--text, #1a1a2e);
}
body.app-light .scs-quick-slot-header {
  background: var(--surface, #fff);
  border-bottom-color: var(--border, rgba(0,0,0,0.08));
}

