/* Build 273 — player calendar pulse for slots posted during the last four hours. */
.mc-slots-day.mc-slots-new-post::after {
  content: "";
  position: absolute;
  inset: -5px;
  z-index: 2;
  border: 2px solid #facc15;
  border-radius: 999px;
  pointer-events: none;
  animation: scsNewSlotDayBlink 1.15s ease-in-out infinite;
}
@keyframes scsNewSlotDayBlink {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: .16; transform: scale(.88); }
}
body.app-light .mc-slots-day.mc-slots-new-post::after {
  border-color: #f59e0b;
}
@media (prefers-reduced-motion: reduce) {
  .mc-slots-day.mc-slots-new-post::after {
    animation: none;
    opacity: 1;
  }
}

