/* Build 353 — Google sign-in design alongside LINE. */
.auth-btn-google {
  width: 100%;
  min-height: 50px;
  padding: 11px 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 11px;
  border: 1px solid #d4d7df;
  border-radius: 14px;
  background: #fff;
  color: #202124;
  font-family: var(--font-body);
  font-size: .96rem;
  font-weight: 750;
  cursor: pointer;
  box-shadow: 0 6px 16px rgba(18,26,53,.10);
  transition: transform .15s ease, background .15s ease, box-shadow .15s ease;
}
.auth-btn-google:hover {
  background: #f8f9fa;
  box-shadow: 0 8px 20px rgba(18,26,53,.14);
}
.auth-btn-google:active { transform: scale(.985); }
.auth-btn-google:disabled {
  cursor: wait;
  opacity: .68;
  transform: none;
}
.auth-google-mark {
  width: 24px;
  height: 24px;
  display: block;
  object-fit: contain;
  flex: 0 0 24px;
}
body.app-dark .auth-btn-google {
  background: #fff;
  border-color: #fff;
