  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.simple-new-slots-dot {
  position: absolute;
  right: -.1rem;
  top: -.08rem;
  width: .38rem;
  height: .38rem;
  border-radius: 50%;
  background: #ff3b30;
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--simple-accent) 10%, #102553);
}
.simple-new-slots-info.is-new-flash {
  animation: simpleNewSlotFlash .7s ease-in-out 43;
}
.simple-new-slots-info.is-new-flash .simple-new-slots-bell {
  animation: simpleNewSlotBell .7s ease-in-out 43;
}
@keyframes simpleNewSlotFlash {
  0%, 100% { opacity: 1; }
  50% { opacity: .38; }
}
@keyframes simpleNewSlotBell {
  0%, 100% { transform: rotate(0deg) scale(1); }
  25% { transform: rotate(-13deg) scale(1.08); }
  75% { transform: rotate(13deg) scale(1.08); }
}
@media (prefers-reduced-motion: reduce) {
  .simple-new-slots-info.is-new-flash,
  .simple-new-slots-info.is-new-flash .simple-new-slots-bell { animation: none; }
}

