/* Build 902 — keep an enabled Start Round CTA visibly inviting until tapped.
   Flat, Glow and Color retain their own treatment; disabled/continue states do not animate. */
@keyframes scsStartReadyFlat {
  0%,100% { transform:scale(1); box-shadow:0 9px 22px rgba(111,48,206,.32), inset 0 1px 0 rgba(255,255,255,.14); filter:brightness(1); }
  50% { transform:scale(1); box-shadow:0 0 0 7px rgba(126,87,194,.13), 0 13px 30px rgba(111,48,206,.42), inset 0 1px 0 rgba(255,255,255,.18); filter:brightness(1.07); }
}
@keyframes scsStartReadyGlow {
  0%,100% { transform:scale(1); box-shadow:0 9px 22px rgba(111,48,206,.32), inset 0 1px 0 rgba(255,255,255,.14); filter:brightness(1); }
  50% { transform:scale(1); box-shadow:0 0 0 7px rgba(91,221,150,.14), 0 0 28px rgba(91,221,150,.42), 0 12px 28px rgba(38,155,91,.22); filter:brightness(1.10); }
}
@keyframes scsStartReadyColor {
  0%,100% { transform:scale(1); filter:brightness(1); box-shadow:0 9px 22px rgba(62,180,111,.20); }
  50% { transform:scale(1); filter:brightness(1.10); box-shadow:0 0 0 7px rgba(255,255,255,.13), 0 14px 32px rgba(62,180,111,.34); }
}
@keyframes scsStartPlayNudge {
  0%,100% { transform:translateX(0) scale(1); }
  50% { transform:translateX(3px) scale(1.06); }
}


body.tile-style-color .org-start-mode-btn:not(:disabled):not(.is-continue) {
