#scsGroupTournament [data-result-card^="positions-"] .scs-tm-shared-name{font-size:13px!important;line-height:1.25;padding:0!important;overflow-wrap:anywhere}
#scsGroupTournament [data-result-card^="positions-"] .scs-tm-ring-slot{flex:none;width:26px!important;height:26px!important;padding:0!important}
