#scsGroupTournament [data-result-card^="positions-"] .scs-team-level-pill,#scsGroupTournament [data-result-card^="positions-"] .scs-team-inline-club-pill{width:auto!important;min-width:0;max-width:100%;height:auto!important;margin:0;padding:2px 4px;font-size:10px!important;line-height:1.3;white-space:normal!important;word-break:normal!important;overflow-wrap:anywhere}
#scsGroupTournament [data-result-card^="positions-"] .scs-gt-result-row>span:nth-child(n+3){grid-row:2;border:0;border-top:1px solid #46607c;padding-top:5px;font-size:12px;text-align:center}
#scsGroupTournament [data-result-card^="positions-"] .scs-gt-result-row>span:nth-child(3){grid-column:2}
#scsGroupTournament [data-result-card^="positions-"] .scs-gt-result-row>span:nth-child(3)::before{content:"W ";color:#b5c9df}
#scsGroupTournament [data-result-card^="positions-"] .scs-gt-result-row>span:nth-child(4)::before{content:"GD ";color:#b5c9df}
#scsGroupTournament [data-result-card^="positions-"] .scs-gt-result-row>span:nth-child(5)::before{content:"PD ";color:#b5c9df}
#scsGroupTournament [data-result-card^="positions-"] .scs-gt-result-row>span:nth-child(4){grid-column:3}
#scsGroupTournament [data-result-card^="positions-"] .scs-gt-result-row>span:nth-child(5){grid-column:4}

/* V842: simple page tabs and a single group selector. */
#scsGroupTournament .scs-results-pages{gap:0;border-bottom:1px solid #39516f;margin-bottom:14px}
#scsGroupTournament .scs-results-pages>button{border:0!important;border-bottom:3px solid transparent!important;border-radius:0!important;background:transparent!important;box-shadow:none!important;color:#b8c6d9;min-height:44px;padding:10px 8px}
#scsGroupTournament .scs-results-pages>button.active{border-bottom-color:#35d1dc!important;color:#67e5eb;background:transparent!important}
#scsGroupTournament .scs-results-group-selector{display:block;margin:0 0 14px}
#scsGroupTournament .scs-results-selector-label{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
#scsGroupTournament [data-results-group-select]{display:block;width:100%;box-sizing:border-box;min-height:44px;padding:10px 12px;border:1px solid #527294;border-radius:8px;background:#162a42;color:#eef4ff;font:inherit;font-weight:650;cursor:pointer}
#scsGroupTournament [data-results-group-select]:focus-visible{outline:2px solid #35d1dc;outline-offset:2px}

/* V843: Group Match Center uses Upcoming and neutral group boundaries. */
#scsGroupTournament .scs-tm-group-fixtures{border:1px solid #46607c!important;border-left:1px solid #46607c!important;border-radius:8px;background:#142238;padding:8px}
#scsGroupTournament .scs-tm-group-fixtures>h4{color:#dce9f7}
#scsGroupTournament .scs-tm-group-fixtures .scs-tm-waiting-match{border-color:#3d5573}
#scsGroupTournament .scs-tm-group-fixtures .scs-tm-waiting-match>b{color:#bcd6ff}

/* V845: format belongs to each event inside a tournament. */
.scs-event-format-label{display:grid;gap:7px;margin:14px 0;font-weight:650}
.scs-event-format-label select{width:100%;min-height:44px;box-sizing:border-box;padding:10px;border:1px solid #527294;border-radius:8px;background:#10213a;color:#eef4ff;font:inherit}
.scs-event-format-caption{display:block;margin:6px 12px;color:#8ddbe2;font-size:12px;line-height:1.4}

/* V846: guided group-size calculation and validation. */
#scsGroupTournament [data-group-setup-status]{padding:10px;border-radius:8px;background:#11343e;color:#9ce6dd;font-size:14px;line-height:1.5}
#scsGroupTournament [data-group-setup-status].is-invalid{background:#3c3020;color:#ffdc9d}
#scsGroupTournament [data-config]:disabled,#scsGroupTournament [data-assist-done="2"]:disabled{opacity:.45;cursor:not-allowed}

/* V848: Welcome cards sit directly on the page without an outer panel. */
#scsRoleWorkspaceChooser .scs-role-chooser-card{width:min(100%,430px);box-sizing:border-box;margin:0;padding:0!important;border:0!important;border-radius:0;background:transparent!important;box-shadow:none!important}
#scsRoleWorkspaceChooser .scs-role-chooser-card>button{width:100%;box-sizing:border-box}
#scsRoleWorkspaceChooser .scs-role-chooser-card>button[data-role-choice]{margin-top:10px}
#scsRoleWorkspaceChooser .scs-role-chooser-card>h2{margin:20px 0 14px}

/* V849: comfortable, symmetrical Welcome page gutters. */
#scsRoleWorkspaceChooser{box-sizing:border-box;padding-left:max(24px,env(safe-area-inset-left))!important;padding-right:max(24px,env(safe-area-inset-right))!important}

/* V851: clear selected state for Normal / Quick player mode. */
#scsPlayerSource .scs-mode-pill>button[aria-pressed="false"]{background:transparent!important;color:#afbed2!important;box-shadow:none!important}
#scsPlayerSource .scs-mode-pill>button.is-active[aria-pressed="true"]{background:#1769d2!important;color:#fff!important;box-shadow:inset 0 0 0 1px #64abff!important;font-weight:750}
#scsPlayerSource .scs-mode-pill>button:focus-visible{outline:2px solid #7bdfea;outline-offset:2px}

/* V852: live walkthrough, without changing the underlying screen. */
.scs-round-guide-ring{position:fixed;z-index:2147483645;pointer-events:none;border:3px solid #ff5c70;border-radius:10px;box-sizing:border-box;box-shadow:0 0 0 2px #fff3,0 0 18px #ff5c7099}
.scs-round-guide-ring::after{content:'';position:absolute;width:14px;height:14px;right:8px;top:8px;background:#fff;border:5px solid #ff5c70;border-radius:50%;animation:scs-guide-tap 1s ease-in-out infinite}
.scs-round-guide-ring[hidden]{display:none!important}
/* V853: one permanent help icon; no instruction card or auto-start. */
.scs-round-guide-info{position:fixed;top:calc(env(safe-area-inset-top,0px) + 12px);right:max(20px,env(safe-area-inset-right));z-index:2147483646;width:44px;height:44px;display:grid;place-items:center;padding:0;border:0;border-radius:50%;background:transparent;color:#79e7e5;font:28px/1 system-ui,sans-serif;cursor:pointer}
.scs-round-guide-info>span{display:block;animation:scs-guide-invite 2s ease-in-out infinite}
.scs-round-guide-info[aria-pressed="true"]{color:#fff;background:#155d6c}
.scs-round-guide-info[aria-pressed="true"]>span{animation:none}
.scs-round-guide-info:focus-visible{outline:2px solid #79e7e5;outline-offset:2px}
.scs-round-guide-live{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
@keyframes scs-guide-invite{50%{transform:scale(1.16);text-shadow:0 0 12px #4de8df}}
@media(prefers-reduced-motion:reduce){.scs-round-guide-info>span{animation:none}}
@keyframes scs-guide-tap{50%{transform:scale(1.35);opacity:.5}}
@media(prefers-reduced-motion:reduce){.scs-round-guide-ring::after{animation:none}}

/* V854: guide launcher belongs only to the Welcome front page. */
.scs-round-guide-info[hidden]{display:none!important}

/* V856: Round Manager's player picker is a child page with its own Done. */
body.scs-round-player-child #scsPracticeSharedHeader{display:none!important}
body.scs-practice-shared-active.scs-round-player-child #playersPage.scs-practice-current-page{padding-top:calc(env(safe-area-inset-top,0px) + 12px)!important;scroll-padding-top:12px!important}
