/* V857: live Mark Winner shortcut shares the existing action row. */
#roundsPage .scs-live-winner-cup[hidden]{display:none!important}
#roundsPage .scs-live-winner-cup{display:grid;place-items:center;flex:0 0 48px;min-height:52px;padding:10px;border:1px solid #576981;border-radius:10px;background:#1c293b;color:#96a3b5;cursor:pointer}
