#roundsPage .action-card:has(>.scs-live-winner-cup:not([hidden]))>#nextBtn{flex:1 1 0;min-width:0;border-radius:10px}

/* V859: the existing dice action shows its current Round Settings mode. */
#roundsPage .action-card>#roundShufle[data-generation-mode="balanced"]:not([hidden]){border-color:#4ed8df!important;background:#12313e!important;color:#8cecf0!important}
