#scsRoleWorkspaceChooser .scs-welcome-tagline{margin:0 0 28px;color:var(--welcome-muted);font-size:18px;font-weight:550}#scsRoleWorkspaceChooser .scs-welcome-tagline i{color:#00b99e;font-style:normal;padding:0 4px}
#scsRoleWorkspaceChooser .scs-role-sport-picker{display:flex;width:100%;gap:0;border:1px solid var(--welcome-line);border-radius:32px;overflow:hidden;margin:0 0 24px;padding:0;background:transparent}
