#scsRoleWorkspaceChooser #scsCentralClubCard{display:grid!important;grid-template-columns:48px 1fr 22px;grid-template-rows:auto auto;gap:3px 15px;box-sizing:border-box;align-items:center;width:100%;min-height:88px;margin:0 0 24px;padding:17px 20px;background:var(--welcome-card);border:0;border-radius:16px;color:var(--welcome-text);text-align:left;box-shadow:none}
