#scsWelcomeEnter{display:flex;align-items:center;justify-content:center;gap:14px;width:100%;min-height:62px;border:0;border-radius:14px;background:linear-gradient(125deg,#00975d,#00884b);color:#fff;font:700 20px system-ui;padding:14px 12px;cursor:pointer}#scsWelcomeEnter b{flex:1;font:inherit}
#scsRoleWorkspaceChooser .scs-welcome-default{display:block;margin:24px 0 0;padding:0;border:0;border-radius:0;background:transparent;box-shadow:none;font-size:16px;color:var(--welcome-muted);cursor:default}#scsRoleWorkspaceChooser .scs-welcome-default strong{color:var(--welcome-text)}
#scsWelcomeModeSettings{box-sizing:border-box;width:calc(100% - 32px);max-width:440px;border:1px solid #405775;border-radius:20px;padding:24px;background:#11253f;color:#f4f8ff;font:16px/1.4 system-ui;max-height:90dvh;overflow:auto}#scsWelcomeModeSettings::backdrop{background:#0009}#scsWelcomeModeSettings header{display:flex;align-items:center;justify-content:space-between}#scsWelcomeModeSettings h2{font-size:23px;margin:0}#scsWelcomeModeSettings header button{width:44px;height:44px;border:0;background:transparent;color:inherit;font-size:28px}#scsWelcomeModeSettings p{color:#b5c8e2}#scsWelcomeModeSettings fieldset{border:0;padding:0;margin:20px 0}#scsWelcomeModeSettings label{display:flex;align-items:center;gap:14px;padding:16px 10px;border-radius:10px;cursor:pointer}#scsWelcomeModeSettings label:has(:checked){background:#19635f}#scsWelcomeModeSettings input{width:20px;height:20px;accent-color:#00bca5}#scsWelcomeModeSettings small{display:block;margin-top:5px;color:#c6d7e9;font-size:13px}#scsWelcomeSaveDefault{width:100%;min-height:48px;border:0;border-radius:10px;background:#00895c;color:white;font:700 16px system-ui}.scs-sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
