  background: #dde3ea !important;
}

body.app-dark .vs-divider .vs-line {
  background: rgba(255,255,255,0.1) !important;
}

.vs-divider span {
  font-family: var(--font-body) !important;
  font-size: 0.58rem !important;
  font-weight: 800 !important;
  color: #b0bac6 !important;
  letter-spacing: 2px !important;
}

/* ─────────────────────────────────────────────
   SWAP ICON
───────────────────────────────────────────── */
.swap-icon {
  position: absolute !important;
  top: 4px !important;
  right: 6px !important;
  z-index: 10 !important;
  background: rgba(0,0,0,0.06) !important;
  color: #8898aa !important;
  border: 1px solid rgba(0,0,0,0.1) !important;
  border-radius: 5px !important;
  padding: 0 !important;
  font-size: 0.8rem !important;
  box-shadow: none !important;
  cursor: pointer !important;
  transition: background 0.15s, color 0.15s !important;
  width: 24px !important;
  height: 18px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}

body.app-dark .swap-icon {
  background: rgba(255,255,255,0.08) !important;
  border-color: rgba(255,255,255,0.12) !important;
  color: #a0a8c0 !important;
}

.swap-icon:hover {
  background: var(--amber) !important;
  color: #fff !important;
  border-color: var(--amber) !important;
}

body.locked .swap-icon { display: none !important; }

/* ─────────────────────────────────────────────
   WIN CUP
───────────────────────────────────────────── */
.win-cup {
  position: absolute !important;
  right: 6px !important;
  bottom: 6px !important;
  left: auto !important;
  transform: none !important;
  width: 26px !important;
  height: 26px !important;
  cursor: pointer !important;
  z-index: 15 !important;
  opacity: 0.6 !important;
  filter: grayscale(20%) !important;
  transition: opacity 0.2s, filter 0.2s, transform 0.2s !important;
}

.win-cup.blinking { animation: winCupBlink2 1.8s infinite !important; }
.win-cup.active   {
  animation: none !important;
  opacity: 1 !important;
  filter: none !important;
  transform: scale(1.25) !important;
}

@keyframes winCupBlink2 {
  0%,100% { opacity: 0.3; transform: scale(0.85); }
  50%     { opacity: 1;   transform: scale(1.05); }
}

/* Live winner prompt: animate every unmarked cup continuously, even if a
   partial round repaint drops the legacy `blinking` helper class. */
#roundsPage.active-mode .win-cup:not(.active) {
  animation: scsWinnerPrompt 1.05s ease-in-out infinite !important;
  transform-origin: center !important;
  will-change: scale, rotate;
}
#roundsPage.active-mode .win-cup.active {
  animation: none !important;
  scale: 1;
  rotate: 0deg;
}
@keyframes scsWinnerPrompt {
  0%   { scale: .80; rotate: -8deg; }
  50%  { scale: 1.22; rotate: 8deg; }
  100% { scale: .80; rotate: -8deg; }
}

/* Keep the result legible on the live court at phone width. */
#roundsPage.active-mode .win-cup.active {
  width: 32px !important;
  height: 32px !important;
  opacity: 1 !important;
  filter: drop-shadow(0 0 8px rgba(255, 206, 55, .9)) !important;
}
.round-score-dashboard {
