/* ── Stop round pill ── */
.stop-round-btn {
  flex-shrink: 0;
  background: rgba(230, 55, 87, 0.15);
  border: 1.5px solid rgba(230, 55, 87, 0.4);
  color: #e63757;
  border-radius: 14px;
  padding: 10px 16px;
