/* Build 779 — compact all-player round history (replaces Rested list) */
.player-history-section { margin-top: 0; padding-left: 12px; min-width: 0; }
.player-history-title { opacity: .9; }
.player-history-box { display: block !important; padding: 3px 0 2px !important; margin-top: 1px !important; opacity: 1; overflow: hidden; }
.player-history-box.rest-collapsed { display: none !important; }
.player-history-scroll { width: 100%; overflow-x: auto; -webkit-overflow-scrolling: touch; }
.player-history-table { border-collapse: collapse; width: max-content; min-width: 100%; font-size: .64rem;  }
.player-history-table th, .player-history-table td { padding: 5px 7px; text-align: center; white-space: nowrap; border-bottom: 1px solid rgba(128,128,128,.16); }
.player-history-table th { font-size: .58rem; opacity: .68; font-weight: 700; }
.player-history-table th:first-child, .player-history-table td:first-child { text-align: left; position: sticky; left: 0; z-index: 2; background: var(--bg, #fff); }
body.dark .player-history-table th:first-child, body.dark .player-history-table td:first-child { background: var(--bg, #111827); }
.player-history-name { max-width: 9rem; overflow: hidden; text-overflow: ellipsis; font-weight: 600; }
.player-history-played-count, .player-history-played { color: #25a84a; font-weight: 700; }
.player-history-rested-count, .player-history-rest { color: #e34b4b; font-weight: 700; }
.player-history-played { font-size: .72rem; }
.player-history-rest { font-size: .82rem; }

@media (max-width: 480px) {
  .player-history-section { padding-left: 7px; }
  .player-history-table { font-size: .56rem; }
  .player-history-table th { font-size: .5rem; }
  .player-history-table th, .player-history-table td { padding: 4px 5px; }
  .player-history-name { max-width: 5.75rem; }
  .player-history-played { font-size: .64rem; }
  .player-history-rest { font-size: .72rem; }
}

/* Player History readability — minimum mobile text size */
.player-history-table {
  font-size: max(.82rem, calc(var(--player-font-size, 1rem) * .72)) !important;
  line-height: 1.25 !important;
}
.player-history-table th {
  font-size: max(.72rem, calc(var(--player-font-size, 1rem) * .64)) !important;
}
.player-history-table th,
.player-history-table td {
  padding: 6px 7px !important;
}
.player-history-played {
  font-size: max(.86rem, calc(var(--player-font-size, 1rem) * .76)) !important;
}
.player-history-rest {
  font-size: max(.9rem, calc(var(--player-font-size, 1rem) * .8)) !important;
}
@media (max-width: 480px) {
  .player-history-table {
    font-size: max(.78rem, calc(var(--player-font-size, 1rem) * .70)) !important;
  }
  .player-history-table th {
    font-size: max(.7rem, calc(var(--player-font-size, 1rem) * .62)) !important;
  }
  .player-history-table th,
  .player-history-table td {
    padding: 5px 6px !important;
  }
  .player-history-name { max-width: 7.5rem !important; }
}

/* Build 791 — Resting + Players: single professional tile components
   One outer card owns the border, radius, background and shadow.
   Header and content are internal regions only — no nested card shells. */

:root {
  --resting-accent: #e63757;
  --players-accent: #4a9eff;
}

/* ----- Shared outer card ----- */
#roundsPage .resting-section,
#roundsPage .player-history-section {
  box-sizing: border-box !important;
  width: calc(100% - 20px) !important;
  margin: 14px 10px 8px !important;
  padding: 0 !important;
  border-radius: 18px !important;
  overflow: hidden !important;
  letter-spacing: normal !important;
}

/* ----- Shared header inside the card ----- */
#roundsPage .resting-section > .resting-toggle-btn,
#roundsPage .player-history-section > .resting-toggle-btn {
  box-sizing: border-box !important;
  width: 100% !important;
  min-height: 42px !important;
  margin: 0 !important;
  padding: 9px 14px !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  background: transparent !important;
  color: var(--text) !important;
  font-size: .76rem !important;
  font-weight: 800 !important;
  letter-spacing: 1.2px !important;
}

/* A divider, not a second card */
#roundsPage .resting-section > .resting-toggle-btn + .rest-box:not(.rest-collapsed),
#roundsPage .player-history-section > .resting-toggle-btn + .player-history-box:not(.rest-collapsed) {
  border-top: 1px solid rgba(255,255,255,.09) !important;
}

/* ----- Content areas: deliberately not cards ----- */
#roundsPage .resting-section > .rest-box,
#roundsPage .player-history-section > .player-history-box {
  box-sizing: border-box !important;
  width: 100% !important;
  margin: 0 !important;
  border: 0 !important;
  outline: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  background: transparent !important;
}

#roundsPage .resting-section > .rest-box:not(.rest-collapsed) {
  display: flex !important;
  padding: 12px 14px 13px !important;
  gap: 8px !important;
}

#roundsPage .player-history-section > .player-history-box:not(.rest-collapsed) {
  display: block !important;
  padding: 0 !important;
}

/* Resting player pills are content, not a second container */
#roundsPage .resting-section .rest-btn {
  margin: 0 !important;
  box-shadow: none !important;
}

/* ----- Player table lives directly in the Players card ----- */
#roundsPage .player-history-scroll,
#roundsPage .player-history-table,
#roundsPage .player-history-table thead,
#roundsPage .player-history-table tbody,
#roundsPage .player-history-table tr {
  background: transparent !important;
}

#roundsPage .player-history-scroll {
  width: 100% !important;
  overflow-x: auto !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}

#roundsPage .player-history-table {
  margin: 0 !important;
  border: 0 !important;
  outline: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}

#roundsPage .player-history-table th,
#roundsPage .player-history-table td {
  background: transparent !important;
  border-left: 0 !important;
  border-right: 0 !important;
}

#roundsPage .player-history-table tbody tr:last-child td {
  border-bottom: 0 !important;
}

/* Sticky Player column must blend into the same card body */


/* ----- FLAT ----- */
body:not(.tile-style-glow):not(.tile-style-color) #roundsPage .resting-section {
  background: rgba(230,55,87,.045) !important;
  border: 1.5px solid rgba(230,55,87,.42) !important;
