.scs-tm-template-entry .scs-tm-ring-slot{width:23px;height:23px}
.scs-tm-template-entry{padding-left:8px;padding-right:8px}

/* V127: Tournament typography uses the same root app zoom as all other screens.
   Use rem units for text; do not apply a second zoom to the overlay or bracket. */
.scs-tm-overlay{font-size:1rem}
.scs-tm-head h2{font-size:clamp(1.3rem,3vw,1.875rem)}
.scs-tm-head p,.scs-tm-hint,.scs-tm-swap-hint{font-size:.875rem}
.scs-tm-kicker,.scs-tm-step{font-size:.75rem}
.scs-tm-head button,.scs-tm-details button,.scs-tm-import-actions button,
.scs-tm-court-options button,.scs-tm-match-assign{font-size:.875rem}
.scs-tm-entry-editor label,.scs-tm-height-control{font-size:.875rem}
.scs-tm-entry-editor input,.scs-tm-entry-editor select{font-size:1rem}
.scs-tm-live-center-head h3{font-size:1.25rem!important}
.scs-tm-live-center-head small,.scs-tm-court-head span{font-size:.75rem}
.scs-tm-court-head strong,.scs-tm-court-teams b{font-size:.875rem}
.scs-tm-waiting-match span,.scs-tm-completed-row span{font-size:.875rem}
.scs-tm-live-tabs button,.scs-tm-live-tabs span{font-size:.875rem}
.scs-tm-upcoming{margin:14px 0 4px;border:1px solid #405a7a;border-radius:14px;background:#111f33;overflow:hidden}
.scs-tm-upcoming>summary{display:flex;align-items:center;gap:9px;min-height:50px;padding:10px 14px;cursor:pointer;list-style:none;color:#f3f7ff;font-weight:800}
.scs-tm-upcoming>summary::-webkit-details-marker{display:none}
.scs-tm-upcoming>summary:before{content:'›';font-size:1.35rem;color:#8f79ff;transform:rotate(0);transition:transform .16s ease}
.scs-tm-upcoming[open]>summary:before{transform:rotate(90deg)}
.scs-tm-upcoming>summary b{display:grid;place-items:center;min-width:24px;height:24px;margin-left:auto;border-radius:50%;background:#263a57;color:#fff;font-size:.8rem}
.scs-tm-upcoming-content{padding:0 10px 10px;border-top:1px solid #30445f}
.scs-tm-template-entry .scs-tm-shared-player{font-size:.8125rem}
.scs-tm-template-entry small{font-size:.625rem}
.scs-tm-template-junction{font-size:.8125rem}
@media(max-width:600px){
 .scs-tm-live-center-head h3{font-size:1.0625rem!important}
 .scs-tm-match-assign{font-size:.75rem}
}

/* V127: prevent tournament action controls from overlapping on mobile/font zoom. */
.scs-tm-tournament-dashboard,.scs-tm-tournament-dashboard *,.scs-tm-start-panel,.scs-tm-start-panel *{box-sizing:border-box}
.scs-tm-dashboard-actions{min-width:0;display:grid;grid-template-columns:minmax(0,2fr) repeat(3,minmax(0,1fr));gap:8px;align-items:stretch}
.scs-tm-dashboard-actions button{min-width:0!important;width:100%;max-width:100%;overflow-wrap:break-word;white-space:normal;line-height:1.25;padding:10px 7px;min-height:52px;border-radius:12px}
.scs-tm-dashboard-actions button span{font-size:inherit;line-height:inherit}
.scs-tm-tournament-dashboard{min-width:0}
.scs-tm-start-panel>.scs-tm-start-live{display:block;width:100%;min-height:48px;padding:12px 16px;border-radius:13px;border:1px solid #54e59c;background:#10b968;color:#fff;font-size:1rem;line-height:1.3;text-align:center;white-space:normal}
@media(max-width:760px){.scs-tm-dashboard-actions{grid-column:1/-1;grid-template-columns:minmax(0,2fr) repeat(3,minmax(0,1fr))}.scs-tm-dashboard-actions .scs-tm-edit-pattern{min-width:0!important;flex:none!important}.scs-tm-dashboard-actions button{font-size:clamp(.75rem,2.5vw,1rem)}}
@media(max-width:400px){.scs-tm-dashboard-actions{grid-template-columns:repeat(2,minmax(0,1fr))}.scs-tm-dashboard-actions button{min-height:46px}}

/* V127: existing components, organized into four sections. */
.scs-tm-organized-tabs{display:grid;gap:5px;margin:0 0 14px;padding:5px;background:#15243a;border:1px solid #41618c;border-radius:14px}
.scs-tm-organized-tabs button{min-width:0;min-height:44px;padding:8px 3px;border:0;border-radius:10px;background:transparent;color:#c9d7eb;font:inherit;font-size:.78rem;font-weight:700;overflow-wrap:anywhere}
.scs-tm-organized-tabs button.active{background:#3267b4;color:#fff}

.scs-tm-tab-panel{min-width:0}
@media(max-width:380px){.scs-tm-organized-tabs button{font-size:.7rem}}

/* V127: entry editor is a mobile dialog, not an inline bracket card. */
.scs-tm-entry-modal{position:fixed;inset:0;z-index:99999;background:rgba(3,9,20,.76);display:flex;align-items:center;justify-content:center;box-sizing:border-box;overscroll-behavior:contain}
.scs-tm-entry-modal .scs-tm-entry-editor{position:relative;width:min(100%,560px);max-height:min(88dvh,850px);overflow-y:auto;overscroll-behavior:contain;box-sizing:border-box;padding:24px 18px;background:#21324b;border:1px solid #6384b0;border-radius:20px;box-shadow:0 24px 60px rgba(0,0,0,.45)}
.scs-tm-entry-modal .scs-tm-entry-editor h3{padding-right:44px}
.scs-tm-entry-modal .scs-tm-entry-close{position:absolute;top:12px;right:12px;width:42px;height:42px;border-radius:50%;border:1px solid #8398b6;background:#34465f;color:white;font-size:1.5rem;line-height:1}

/* V149: one complete card per match, title above two team rows and score. */
.scs-tm-completed-row{display:block;overflow:hidden;padding:0;margin:12px 0;border:1px solid #456b9b;border-left:5px solid #8763f5;border-radius:17px;background:#112138;color:#e9f1ff;min-width:0}
.scs-tm-completed-title{display:flex;align-items:center;gap:12px;padding:12px 15px;background:linear-gradient(110deg,#29366a,#1c355d);border-bottom:1px solid #4a6492;font-size:1.02rem}
.scs-tm-completed-check{display:grid;place-items:center;border:1px solid #9a80ff;border-radius:50%;background:#453e81;width:30px;height:30px;flex-shrink:0;color:#fff;font-weight:900}
.scs-tm-completed-content{grid-template-columns:minmax(0,1.25fr) minmax(0,1fr);gap:12px;align-items:center;}
.scs-tm-completed-teams{display:flex;flex-direction:column;min-width:0}
.scs-tm-completed-team{flex-direction:column;min-width:0;}
.scs-tm-completed-team .scs-tm-shared-player{display:flex;align-items:center;gap:7px;min-width:0;font-size:.85rem;font-weight:650;overflow-wrap:anywhere}
.scs-tm-completed-team .scs-tm-ring-slot{flex:0 0 28px;min-width:28px;min-height:28px}
.scs-tm-completed-vs{font-weight:800;letter-spacing:.08em;margin-left:33px}
.scs-tm-completed-result{border-left:1px solid #4a6283;padding-left:12px;min-width:0}
.scs-tm-completed-result strong{display:block;font-size:1.3rem;line-height:1.3;color:#68dfb2}
.scs-tm-completed-result small{display:block;margin-top:8px;color:#a6b8d4;overflow-wrap:anywhere;grid-column:auto;font-size:.76rem}
.scs-tm-completed-result small b{color:#e8f0ff}
@media(max-width:380px){.scs-tm-completed-content{grid-template-columns:minmax(0,1fr) minmax(0,.9fr);gap:7px;padding:9px}.scs-tm-completed-result{padding-left:8px}.scs-tm-completed-result strong{font-size:1.08rem}}

/* V149: One shared completed-match card: scores alongside teams, winner below. */
.scs-tm-completed-content{display:block;}

.scs-tm-completed-team{display:grid;align-items:center;gap:8px;}
.scs-tm-completed-players{display:flex;flex-direction:column;gap:5px;}
.scs-tm-completed-team-score{font-size:1.35rem!important;font-weight:850;color:#e8f0ff!important;text-align:right;font-variant-numeric:tabular-nums}
.scs-tm-completed-team.is-winner .scs-tm-completed-team-score{color:#62e4b4!important}
.scs-tm-serving-player{display:flex;align-items:center;justify-content:flex-start;gap:5px;min-width:0;width:100%}.scs-tm-serving-player>.scs-tm-shared-player{flex:0 1 auto;min-width:0}.scs-tm-server-shuttle{flex:0 0 auto;display:inline-grid;place-items:center;width:23px;height:23px;border-radius:50%;background:#f6c945;color:#101827;font-size:13px;line-height:1;box-shadow:0 0 0 2px rgba(246,201,69,.18)}.scs-tm-completed-players{min-width:0}.scs-tm-completed-team{column-gap:14px!important}.scs-tm-bracket-player-service{display:flex;align-items:center;justify-content:flex-start;gap:3px;width:100%;min-width:0}.scs-tm-bracket-player-service>.scs-tm-shared-player{flex:0 1 auto;min-width:0}.scs-tm-template-entry .scs-tm-server-shuttle{width:18px;height:18px;font-size:10px;box-shadow:0 0 0 1px rgba(246,201,69,.22)}
.scs-tm-completed-vs{text-align:center;font-size:.72rem}
.scs-tm-completed-content{padding:8px 0 3px}.scs-tm-completed-teams{gap:0}.scs-tm-completed-team{border:0;border-radius:0;background:transparent;padding:12px 10px}.scs-tm-completed-team.is-leading{background:linear-gradient(90deg,rgba(18,178,205,.18),rgba(18,178,205,.07))}.scs-tm-completed-team.is-leading .scs-tm-completed-team-score{color:#28d7ef!important}.scs-tm-completed-vs{display:flex;align-items:center;gap:9px;margin:2px 10px;color:#9fc5ff}.scs-tm-completed-vs::before,.scs-tm-completed-vs::after{content:'';height:1px;flex:1;background:#365a82}
.scs-tm-completed-winner{display:flex;align-items:center;gap:9px;margin-top:10px;padding:9px 12px;border:1px solid #20a67b;border-radius:11px;background:#103b39;min-width:0}
.scs-tm-completed-winner>span:first-child{font-size:1.45rem;flex-shrink:0}
.scs-tm-completed-winner>span:last-child{display:flex;flex-direction:column;gap:2px;min-width:0}
.scs-tm-completed-winner small{color:#65e8b6;font-weight:800}
.scs-tm-completed-winner b{color:#fff;overflow-wrap:anywhere}
@media(max-width:380px){.scs-tm-completed-content{padding:8px}.scs-tm-completed-team{padding:7px}.scs-tm-completed-team-score{font-size:1.1rem!important}}

/* Shared Match Center: color-coded round-robin groups; knockout unchanged. */
.scs-tm-group-fixtures{--group-accent:#8d79ff;margin:12px 0 16px;padding:12px;border:1px solid color-mix(in srgb,var(--group-accent) 70%,transparent);border-left:5px solid var(--group-accent);border-radius:16px;background:color-mix(in srgb,var(--group-accent) 13%,#142238)}
.scs-tm-group-fixtures>h4{display:flex;justify-content:space-between;align-items:center;gap:8px;margin:2px 4px 10px;color:var(--group-accent);font-size:1rem;letter-spacing:.02em}
.scs-tm-group-fixtures>h4 span{font-size:.76rem;font-weight:600;color:#c3d0e4;white-space:nowrap}
.scs-tm-group-fixtures-list{display:grid;gap:8px}
.scs-tm-group-fixtures .scs-tm-waiting-match{margin:0;min-width:0;grid-template-columns:minmax(40px,auto) minmax(0,1fr) auto;gap:9px;padding:10px 9px;border-color:color-mix(in srgb,var(--group-accent) 34%,#30445f)}
.scs-tm-group-fixtures .scs-tm-waiting-match>b{width:auto;height:auto;min-width:40px;display:block;border:0;border-radius:0;color:var(--group-accent);font-size:.78rem;overflow-wrap:anywhere;text-align:center;line-height:1.35}
.scs-tm-group-fixtures .scs-tm-waiting-match>span{min-width:0;overflow-wrap:anywhere;font-size:.84rem;line-height:1.4}
.scs-tm-group-fixtures .scs-tm-match-assign{min-width:66px;padding:9px 8px}
.scs-tm-court-card[class*="scs-tm-group-tone-"]{border-left:5px solid var(--group-accent);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--group-accent) 16%,transparent)}
.scs-tm-group-tone-0{--group-accent:#9c86ff}.scs-tm-group-tone-1{--group-accent:#58c6d9}.scs-tm-group-tone-2{--group-accent:#f0b25c}.scs-tm-group-tone-3{--group-accent:#72d8a0}.scs-tm-group-tone-4{--group-accent:#f18bb9}.scs-tm-group-tone-5{--group-accent:#8eaeff}.scs-tm-group-tone-6{--group-accent:#e1ca70}.scs-tm-group-tone-7{--group-accent:#c69ff5}
@media(max-width:430px){.scs-tm-group-fixtures{padding:9px}.scs-tm-group-fixtures .scs-tm-waiting-match{grid-template-columns:minmax(36px,auto) minmax(0,1fr) auto;gap:6px;padding:9px 6px}.scs-tm-group-fixtures .scs-tm-match-assign{min-width:58px;font-size:.76rem;padding:9px 6px}}
/* V157: reuse the existing bracket and Match Center in one tabbed workspace. */
.scs-tm-center-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;margin:12px 0 16px;padding:6px;border:1px solid #47668b;border-radius:16px;background:#15263e}
.scs-tm-center-tabs button{min-width:0;padding:12px 4px;border:0;border-radius:11px;background:transparent;color:#d6e0f0;font-weight:700;font-size:14px}
.scs-tm-center-tabs button.active{background:#3768b2;color:#fff}
[data-tm-center-panel][hidden],.scs-tm-tab-panel[hidden]{display:none!important}

/* V164: one tournament navigation row; courts and match lists stay together. */
.scs-tm-organized-tabs{grid-template-columns:repeat(3,minmax(0,1fr))}
.scs-tm-organized-tabs:has(button:nth-child(4)){grid-template-columns:repeat(4,minmax(0,1fr))}

/* V165: explicit SCS Home navigation above live tournament tabs */
.scs-tm-home-row{display:flex;justify-content:flex-start;margin:0 0 12px}
.scs-tm-home-button{cursor:pointer}

/* V166: practice-style fixed bottom navigation for live knockout tournaments. */

.scs-tm-bottom-nav{position:fixed;bottom:0;left:0;right:0;z-index:10050;display:grid;gap:0!important;margin:0!important;padding:8px 5px calc(8px + env(safe-area-inset-bottom))!important;background:#0d0c13!important;border:0!important;border-top:1px solid #343344!important;border-radius:0!important;box-shadow:0 -3px 12px #0005;}
.scs-tm-bottom-nav button{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;min-height:62px!important;padding:5px 1px!important;border:0!important;background:transparent!important;color:#a5a4b1!important;border-radius:0!important;font-size:11px!important;overflow-wrap:normal!important;}
.scs-tm-bottom-nav button.active{color:#8768ff!important;}
.scs-tm-bottom-nav button.active:after{content:'';display:block;width:30px;height:3px;background:#8768ff;border-radius:6px;position:absolute;bottom:calc(6px + env(safe-area-inset-bottom));}
.scs-tm-bottom-nav .scs-tm-nav-icon{font-size:25px;line-height:1.1;font-weight:600;}
.scs-tm-bottom-nav .scs-tm-nav-label{font-weight:700;}

/* V290: Knockout uses the same four-section navigation as Team Tournament. */
.scs-tm-overlay:has(.scs-tm-bottom-nav){padding-bottom:calc(104px + env(safe-area-inset-bottom));}
.scs-tm-tab-panel[hidden]{display:none!important;}
.scs-tm-bottom-nav button{position:relative;}

/* Group Tournament owns child knockouts. Keep only the bracket and Match Center
   surfaces so the child never looks like a separate standalone tournament. */
.scs-tm-overlay.scs-tm-group-child .scs-tm-bottom-nav{grid-template-columns:repeat(2,minmax(0,1fr))!important}
.scs-tm-overlay.scs-tm-group-child .scs-tm-tournament-dashboard .scs-tm-kicker{color:#8fc5ff}
.scs-tm-overlay.scs-tm-group-child .scs-tm-group-start-guide{border-color:#4e92e3;background:#142d4b}
.scs-tm-overlay.scs-tm-group-child .scs-tm-group-back{position:sticky;top:0;z-index:10020;margin:0 0 10px;padding:10px 14px;border:1px solid #4e92e3;border-radius:10px;background:#142d4b;color:#eaf4ff;font:inherit;font-weight:750;cursor:pointer}
.scs-tm-overlay.scs-tm-group-child .scs-tm-start-live{display:block;width:100%;max-width:none;margin:16px auto;padding:14px 18px;text-align:center}
.scs-tm-overlay.scs-tm-group-child .scs-tm-live-courts{display:flex!important;flex-direction:column!important;width:100%!important}
.scs-tm-overlay.scs-tm-group-child .scs-tm-court-card{width:100%!important;min-width:0!important}
.scs-tm-overlay.scs-tm-group-child .scs-tm-court-teams{grid-template-columns:minmax(0,1fr)!important;width:100%!important}
.scs-tm-overlay.scs-tm-group-child .scs-tm-serving-player,.scs-tm-overlay.scs-tm-group-child .scs-match-player-identity,.scs-tm-overlay.scs-tm-group-child .scs-match-player-name{width:100%!important;max-width:100%!important;min-width:0!important}
.scs-tm-overlay.scs-tm-group-child .scs-tm-shared-name{white-space:normal!important;overflow-wrap:break-word!important;word-break:normal!important}
/* V291 Knockout multi-event home — shares Team Tournament navigation vocabulary. */
.scs-ko-event-home{padding:18px 14px 110px;max-width:820px;margin:0 auto;color:var(--text-primary,#eaf0fb)}
.scs-ko-event-home header{padding:0 4px 15px;border-bottom:1px solid #40506a}
.scs-ko-event-home header h2{font-size:22px;margin:0 0 4px}
.scs-ko-event-home header small{opacity:.7}
.scs-ko-event-home section{margin-top:18px}
.scs-ko-event-home section h3{font-size:14px;margin:0 0 8px}
.scs-ko-event-row{display:flex;align-items:center;gap:12px;width:100%;text-align:left;color:inherit;background:#22324a;border:1px solid #3a4a62;border-radius:12px;padding:13px 12px;margin:8px 0;cursor:pointer}
.scs-ko-event-row.active{border:2px solid #61b6f6;background:#294468}
.scs-ko-event-code{min-width:60px;text-align:center;background:#8ecdfb;color:#102238;border-radius:16px;font-size:12px;font-weight:800;padding:6px 9px}
.scs-ko-event-code.L{background:#f6a5ce}
.scs-ko-event-detail{flex:1;min-width:0;display:flex;flex-direction:column;gap:3px}
.scs-ko-event-detail strong{font-size:14px;overflow-wrap:anywhere}
.scs-ko-event-detail small{font-size:12px;opacity:.72}
.scs-ko-event-detail em{font-size:12px;color:#81e6ad;font-style:normal;font-weight:700}
.scs-ko-empty{font-size:12px;opacity:.65;padding:5px}
.scs-ko-add-event{width:100%;background:#2869ba;color:white;border:0;border-radius:12px;font-size:15px;font-weight:700;padding:15px;margin:18px 0}

.scs-ko-rename{background:transparent;border:0;color:#9dc9fa;font-size:12px;padding:3px 0 6px;text-align:left}

/* V294: Restore clear in-step pattern preview before confirmation. */
.scs-tm-pattern-preview-heading{display:flex;flex-direction:column;gap:4px;padding:10px 12px;margin:0 0 8px;background:#203552;border:1px solid #5478a7;border-radius:12px;color:#f4f8ff}
.scs-tm-pattern-preview-heading strong{font-size:14px}.scs-tm-pattern-preview-heading span{font-size:12px;color:#bdd0e9}
.scs-tm-pattern-dashboard + .scs-tm-workspace{margin-top:8px}

/* V304: full-width tournament player rows with the proven Team Tournament sub-club pill. */
.scs-tm-player-pool .scs-tm-pool-chips{display:flex;flex-direction:column;align-items:stretch;gap:9px;width:100%}
.scs-tm-player-pool .scs-api-roster-row{display:flex;align-items:center;justify-content:space-between;gap:10px;min-width:0;width:100%;box-sizing:border-box;padding:10px 12px;border:1px solid rgba(130,160,205,.35);border-radius:12px;background:#34486a}
.scs-tm-player-pool .scs-api-roster-row .scs-tm-shared-player{display:flex;align-items:center;flex:1 1 auto;min-width:0;padding:0;border:0;background:transparent}
.scs-tm-player-pool .scs-api-roster-row .scs-tm-shared-name{flex:1 1 auto;min-width:0}
.scs-tm-player-pool .scs-api-roster-row .scs-tournament-gender-level{flex:0 0 auto}
.scs-tm-player-pool .scs-api-subclub-pill{display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto;border-radius:999px;padding:3px 10px;max-width:45%;background:color-mix(in srgb,var(--pill-accent) 60%,#17263d 40%);color:#fff;font-size:.72rem;font-weight:650;line-height:1.4;white-space:normal;text-align:center}
body.light-mode .scs-tm-player-pool .scs-api-subclub-pill{background:color-mix(in srgb,var(--pill-accent) 35%,#fff 65%);color:#15233a}

/* V330: Generated knockout matches reuse shared SCS match cards. */
.scs-ko-generated-fixtures{margin:14px 0;border:1px solid #4c6485;border-radius:16px;background:#1b2b44;color:#f3f6ff}
.scs-ko-generated-fixtures>h3{margin:4px 0 16px;font-size:1.2rem}
.scs-ko-fixture-round{margin:12px 0 20px}
.scs-ko-fixture-round>h4{margin:0 0 8px;font-size:1rem;color:#b9cdea}
.scs-ko-fixture-card{border:1px solid #4c6485;overflow:hidden}
.scs-ko-fixture-card .scs-tm-completed-row{margin:0;border:0;border-radius:0}
.scs-ko-fixture-pending{display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:50%;border:1px solid #94a8c8;color:#b8cbe8}
.scs-ko-fixture-actions{display:flex;flex-wrap:wrap;align-items:center;background:#223550}
.scs-ko-fixture-actions button{background:#3467b3;color:white;border:1px solid #739be0;border-radius:10px;font:inherit;font-weight:650}
.scs-ko-fixture-actions button{width:100%;flex:1 1 100%}
.scs-ko-fixture-actions span{color:#c6d7ec}

/* V331: Compact knockout team roster and generated match layout. */
