/* V392: canonical match-card presentation for ALL tournaments.
   The card HTML is generated exclusively by SCSSharedMatchCenter.completed().
   Tournament wrappers are allowed, but cannot restyle the inner match card. */
:where(.scs-team-sheet,.scs-ko-generated-fixtures,.scs-tm-unified-match-center) .scs-tm-completed-row,
.scs-team-sheet .scs-team-match-shell .scs-tm-completed-row{
  display:block!important;width:100%!important;max-width:none!important;box-sizing:border-box!important;
  margin:10px 0!important;padding:0!important;border:1px solid #456b9b!important;
  border-radius:16px!important;overflow:hidden!important;background:#112138!important;box-shadow:none!important;
}
:where(.scs-team-sheet,.scs-ko-generated-fixtures,.scs-tm-unified-match-center) .scs-tm-completed-title,
.scs-team-sheet .scs-team-match-shell .scs-tm-completed-title{
  display:flex!important;align-items:center!important;gap:12px!important;padding:12px 15px!important;
  background:linear-gradient(110deg,#29366a,#1c355d)!important;border-bottom:1px solid #4a6492!important;
}
:where(.scs-team-sheet,.scs-ko-generated-fixtures,.scs-tm-unified-match-center) .scs-tm-completed-content,
.scs-team-sheet .scs-team-match-shell .scs-tm-completed-content{
 display:block!important;padding:0!important;background:#101d30!important;
}
:where(.scs-team-sheet,.scs-ko-generated-fixtures,.scs-tm-unified-match-center) .scs-tm-completed-teams,
.scs-team-sheet .scs-team-match-shell .scs-tm-completed-teams{
 display:flex!important;flex-direction:column!important;gap:0!important;
}
:where(.scs-team-sheet,.scs-ko-generated-fixtures,.scs-tm-unified-match-center) .scs-tm-completed-team,
.scs-team-sheet .scs-team-match-shell .scs-tm-completed-team{
 display:grid!important;grid-template-columns:minmax(0,1fr) max-content!important;grid-template-rows:auto!important;
 gap:10px!important;align-items:center!important;margin:0!important;padding:13px 12px!important;
 border:0!important;border-radius:0!important;min-width:0!important;
}
:where(.scs-team-sheet,.scs-ko-generated-fixtures,.scs-tm-unified-match-center) .scs-tm-completed-team:first-child,
.scs-team-sheet .scs-team-match-shell .scs-tm-completed-team:first-child{background:#1c3c65!important}
:where(.scs-team-sheet,.scs-ko-generated-fixtures,.scs-tm-unified-match-center) .scs-tm-completed-team:last-child,
.scs-team-sheet .scs-team-match-shell .scs-tm-completed-team:last-child{background:#493047!important}
:where(.scs-team-sheet,.scs-ko-generated-fixtures,.scs-tm-unified-match-center) .scs-tm-completed-players,
.scs-team-sheet .scs-team-match-shell .scs-tm-completed-players{
 display:flex!important;flex-direction:column!important;grid-column:1!important;grid-row:1!important;
 gap:9px!important;padding:0!important;min-width:0!important;
}
:where(.scs-team-sheet,.scs-ko-generated-fixtures,.scs-tm-unified-match-center) .scs-tm-completed-team-score,
.scs-team-sheet .scs-team-match-shell .scs-tm-completed-team-score{
 display:block!important;grid-column:2!important;grid-row:1!important;align-self:center!important;
 justify-self:end!important;padding:0!important;margin:0!important;text-align:right!important;
