.scs-team-sheet .scs-match-player-identity{
 display:flex!important;flex-direction:column!important;align-items:flex-start!important;gap:4px!important;min-width:0!important;
}
:where(.scs-team-sheet,.scs-ko-generated-fixtures,.scs-tm-unified-match-center) .scs-match-player-meta,
.scs-team-sheet .scs-match-player-meta{
