#scsScoringOverlay #scsScoreFormatDetails{--sets-head:#0d2d59;--sets-selected:#0759ca;--sets-bg:#112a49;--sets-row:#193958;--sets-band:#244c78;--sets-input:#234666;--sets-ink:#f1f6ff;--sets-line:#617c9f;--sets-badge:#c8e5ff;--sets-badge-ink:#102747;--sets-final:#244c3b;box-sizing:border-box;margin:0;border:1px solid var(--sets-line);border-radius:16px;background:var(--sets-bg);color:var(--sets-ink);overflow:hidden;box-shadow:0 5px 15px rgba(0,0,0,.1);}
#scsScoringOverlay[data-scoring-sport="pickleball"] #scsScoreFormatDetails{--sets-head:#0b4033;--sets-selected:#08734f;--sets-bg:#113c32;--sets-row:#194b3f;--sets-band:#286953;--sets-input:#235d4e;--sets-ink:#effaf5;--sets-line:#638e7e;--sets-badge:#c7edda;--sets-badge-ink:#123b2d;--sets-final:#3d5c32;}
body.app-light #scsScoringOverlay #scsScoreFormatDetails,html.app-light #scsScoringOverlay #scsScoreFormatDetails{--sets-bg:#fff;--sets-row:#f6f9fe;--sets-band:#d0e5ff;--sets-input:#e7f1ff;--sets-ink:#102747;--sets-line:#b9cce4;--sets-final:#e7f3db;}
body.app-light #scsScoringOverlay[data-scoring-sport="pickleball"] #scsScoreFormatDetails,html.app-light #scsScoringOverlay[data-scoring-sport="pickleball"] #scsScoreFormatDetails{--sets-row:#f5fbf7;--sets-band:#cfeada;--sets-input:#e2f2e9;--sets-ink:#123b2d;--sets-line:#accfba;--sets-final:#eaf2d7;}
#scsScoringOverlay #scsScoreFormatDetails>summary{box-sizing:border-box;display:flex;justify-content:flex-start;gap:10px;min-height:64px;padding:12px 14px;background:linear-gradient(120deg,var(--sets-selected),var(--sets-head));color:#fff;font-size:20px;font-weight:750;}
#scsScoringOverlay #scsScoreFormatDetails>summary::after{content:'';box-sizing:border-box;flex:0 0 11px;width:11px;height:11px;margin:0 3px 4px auto;border:solid currentColor;border-width:0 2px 2px 0;transform:rotate(45deg);}
#scsScoringOverlay #scsScoreFormatDetails[open]>summary::after{transform:rotate(225deg);margin-bottom:-4px;}
#scsScoringOverlay #scsScoreFormatDetails.is-locked>summary::after{content:'🔒';width:auto;height:auto;flex-basis:auto;border:0;transform:none;font-size:16px;}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-sets-icon{width:26px;height:26px;flex:0 0 26px;}
#scsScoringOverlay #scsScoreUnit{padding-right:14px;border-right:1px solid rgba(255,255,255,.55);}
#scsScoringOverlay #scsScoreFormatSummary{padding:6px 14px;border-radius:999px;background:var(--sets-badge);color:var(--sets-badge-ink);font-size:18px;line-height:1.3;white-space:nowrap;}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-format-content{padding:14px 12px 16px;}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-match-format{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px;margin:0 0 12px;padding:10px;border:1px solid var(--sets-line);border-radius:11px;background:var(--sets-input);}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-match-format>strong{display:flex;align-items:center;gap:7px;font-size:16px;line-height:1.25;color:var(--sets-ink);}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-format-sport-icon{width:26px;height:26px;flex:0 0 26px;}
#scsScoringOverlay .scs-score-format-paddle{display:none;}
#scsScoringOverlay[data-scoring-sport="pickleball"] .scs-score-format-paddle{display:initial;}
