#scsScoringOverlay #scsScoreFormatDetails .scs-score-match-format>div{display:flex;flex:1 1 170px;gap:8px;min-width:0;max-width:260px;}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-match-format label{flex:1;min-width:0;position:relative;}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-match-format label>span{box-sizing:border-box;display:flex;align-items:center;justify-content:center;gap:6px;min-height:44px;min-width:0;padding:8px 10px;border:1px solid var(--sets-line);border-radius:9px;background:var(--sets-bg);color:var(--sets-ink);font-size:16px;font-weight:750;white-space:nowrap;}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-match-format label>span>span{padding:0;border:0;min-height:0;background:transparent;font:inherit;color:inherit;}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-match-format input:checked+span{background:var(--sets-selected);border-color:var(--sets-selected);color:#fff;box-shadow:none;}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-match-format input:checked+span::before{content:'✓';display:grid;place-items:center;width:19px;height:19px;border-radius:50%;background:#fff;color:var(--sets-selected);font-size:14px;line-height:1;}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-match-format input:focus-visible+span{outline:2px solid var(--sets-selected);outline-offset:3px;}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-set-rules{display:grid;gap:10px;margin:0;}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-set-rule{position:relative;box-sizing:border-box;display:grid;grid-template-columns:64px minmax(0,1fr) minmax(0,1fr);align-items:center;gap:9px;min-height:58px;padding:7px 10px 7px 0;border:1px solid var(--sets-line);border-radius:10px;background:var(--sets-row);overflow:hidden;}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-set-rule>strong{position:relative;display:flex;align-items:center;align-self:stretch;padding-left:12px;font-size:18px;white-space:nowrap;isolation:isolate;}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-set-rule>strong::before{content:'';position:absolute;inset:-8px -12px -8px 0;z-index:-1;background:var(--sets-band);clip-path:polygon(0 0,100% 0,76% 100%,0 100%);}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-set-rule label{display:flex;align-items:center;justify-content:space-between;gap:6px;min-width:0;color:var(--sets-ink);font-size:16px;}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-set-rule label+label{padding-left:9px;border-left:1px solid var(--sets-line);}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-set-rule input{box-sizing:border-box;width:54px;min-width:0;height:42px;padding:5px 3px;border:1px solid var(--sets-line);border-radius:9px;background:var(--sets-input);color:var(--sets-ink);font:750 20px/1.2 system-ui;text-align:center;appearance:textfield;}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-set-rule input::-webkit-inner-spin-button,#scsScoringOverlay #scsScoreFormatDetails .scs-score-set-rule input::-webkit-outer-spin-button{-webkit-appearance:none;margin:0;}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-set-rule[data-set="3"] input{background:var(--sets-final);}
#scsScoringOverlay #scsScoreFormatDetails .scs-score-set-rule input:focus{outline:2px solid var(--sets-selected);outline-offset:1px;}
#scsScoringOverlay[data-scoring-sport="pickleball"] #scsScoreFormatDetails .scs-score-set-rule{grid-template-columns:80px minmax(0,1fr);}
#scsScoringOverlay[data-scoring-sport="pickleball"] #scsScoreFormatDetails .scs-score-set-rule label{justify-content:flex-end;gap:18px;}
#scsScoringOverlay #scsScoreFormatDetails [hidden]{display:none!important;}
@media(max-width:380px){
 #scsScoringOverlay #scsScoreFormatDetails .scs-score-format-content{padding:10px 8px 12px;}
 #scsScoringOverlay #scsScoreFormatDetails .scs-score-set-rule{grid-template-columns:55px minmax(0,1fr) minmax(0,1fr);gap:6px;padding-right:7px;}
 #scsScoringOverlay #scsScoreFormatDetails .scs-score-set-rule>strong{padding-left:8px;font-size:16px;}
