#scsSlotManagerRefresh:disabled{opacity:.5;cursor:wait}
#scsSlotManagerRefresh:focus-visible{outline:2px solid currentColor;outline-offset:2px}

/* V931: compact slot options, separate from the expand arrow. */
.scs-slot-options-pill{display:inline-flex;align-items:center;justify-content:center;flex:0 0 44px;min-width:44px;height:36px;padding:0 10px;border:1px solid currentColor;border-radius:999px;background:transparent;color:inherit;font:700 24px/1 system-ui;cursor:pointer}
.mc-slot-time-row > .scs-slot-options-pill{margin-left:auto;margin-right:8px}
.scs-simple-slot-row{position:relative}
.scs-simple-slot-row:has(> .scs-slot-options-pill) > .scs-simple-slot-toggle{padding-right:64px}
.scs-simple-slot-row > .scs-slot-options-pill{position:absolute;right:12px;top:16px}
.scs-slot-options-menu{position:fixed;z-index:2147483000;min-width:140px;padding:6px;border:1px solid var(--border,#607b98);border-radius:12px;background:var(--card,#12304b);color:var(--text,#fff);box-shadow:0 6px 20px #0004}
.scs-slot-options-menu button{display:block;width:100%;min-height:44px;padding:10px 16px;border:0;border-radius:8px;background:transparent;color:inherit;text-align:left;font:600 16px/1.4 system-ui;cursor:pointer}
.scs-slot-options-menu button:focus-visible,.scs-slot-options-menu button:hover{background:#ffffff18;outline:2px solid var(--accent,#5ba9ff)}
.scs-slot-options-pill:focus-visible{outline:2px solid var(--accent,#5ba9ff);outline-offset:2px}

#vaultUpcomingSlots .scs-simple-slot-row:has(> .scs-slot-options-pill) > .scs-simple-slot-toggle{padding-right:64px!important}

/* V932: player rows support tapping for arrival order. */
.scs-arrival-row{cursor:pointer;-webkit-tap-highlight-color:transparent}

/* V934: separate Scoreboard app home, existing scoring UI remains shared. */
#scsScoreboardAppHome{position:fixed;inset:0;z-index:10000;overflow:auto;background:var(--bg,#071A35);color:var(--text,#fff);padding:calc(env(safe-area-inset-top) + 22px) 24px 32px;font:16px/1.5 system-ui}
#scsScoreboardAppHome[hidden]{display:none!important}
#scsScoreboardAppHome header{display:flex;align-items:center;justify-content:space-between;gap:16px;max-width:480px;margin:auto}
#scsScoreboardAppHome h1{font-size:24px;margin:0}
#scsScoreboardAppHome h2{font-size:26px;text-align:center;margin:14px 0 8px}
#scsScoreboardAppHome p{max-width:480px;margin:8px auto 20px;text-align:center}
#scsScoreboardAppHome button,#scsScoreboardAppHome select{font:600 16px/1.4 system-ui;min-height:44px;border:1px solid var(--border,#607b98);border-radius:12px;padding:10px 14px;background:var(--card,#12304b);color:inherit;cursor:pointer}
#scsScoreboardAppHome .scs-scoreboard-app-icon{display:block;width:100px;height:100px;border-radius:20px;margin:30px auto 0}
.scs-scoreboard-sports{display:flex;gap:10px;max-width:480px;margin:24px auto}
.scs-scoreboard-sports button{flex:1}
#scsScoreboardAppHome [aria-pressed="true"]{background:var(--accent,#176bd5);border-color:#7ac8ff}
#scsScoreboardAppHome label,#scsScoreboardAppHome select{display:block;width:100%;max-width:480px;box-sizing:border-box;margin:8px auto}
#scsScoreboardAppHome label span{font-size:14px;opacity:.75}
#scsScoreboardAppHome .scs-scoreboard-open{display:block;width:100%;max-width:480px;margin:24px auto 14px;background:var(--accent,#176bd5);font-size:18px;min-height:54px}
.scs-scoreboard-apps{display:block;text-align:center;color:inherit;margin-top:22px}
#scsSportAppLinks a[data-sport="scoreboard"],#scsAuthSportAppLinks a[data-sport="scoreboard"]{grid-column:1/-1}

/* V935: four standalone apps form a compact two-by-two welcome chooser. */
#scsSportAppLinks a[data-sport="scoreboard"],#scsAuthSportAppLinks a[data-sport="scoreboard"],
#scsSportAppLinks a[data-sport="tournaments"],#scsAuthSportAppLinks a[data-sport="tournaments"]{grid-column:auto}

/* V938: scoring-only picker chrome in the standalone Scoreboard PWA. */
html[data-scs-app="scoreboard"] #scsPracticeSharedHeader .scs-phase1-ref-drawer{display:none!important}
html[data-scs-app="scoreboard"]:has(#scsScoringOverlay:not([hidden]) #scsScoreMatchPicker:not([hidden])) #scsPracticeSharedHeader{display:none!important}
html[data-scs-app="scoreboard"] #scsScoringOverlay:has(#scsScoreMatchPicker:not([hidden])){top:0!important;padding-top:env(safe-area-inset-top,0px)!important}
.scs-scoreboard-picker-header{position:sticky;top:0;z-index:5;display:flex;align-items:center;gap:12px;min-height:56px;padding:6px 0;background:var(--bg,#071A35)}
.scs-scoreboard-picker-header strong{flex:1;font-size:20px;line-height:1.3;text-align:center}
.scs-scoreboard-picker-header button{display:inline-flex;align-items:center;justify-content:center;flex:0 0 44px;width:44px;height:44px;padding:0;border:1px solid var(--border,#607b98);border-radius:12px;background:transparent;color:inherit;font:600 26px/1 system-ui;cursor:pointer}
.scs-scoreboard-picker-header button:disabled{opacity:.5;cursor:wait}
.scs-scoreboard-picker-header button:focus-visible{outline:2px solid var(--accent,#7ac8ff);outline-offset:2px}
html[data-scs-app="scoreboard"] #scsScoreMatchPicker > .scs-score-picker-title{margin-top:10px}

/* V939: Tournament PWA welcome only; shared welcome and manager UI stay intact. */
html[data-scs-app="tournaments"] #scsRoleWorkspaceChooser #scsCentralClubCard{display:grid!important}
html[data-scs-app="tournaments"] #scsRoleWorkspaceChooser #scsWelcomeEnter{display:flex!important}
html[data-scs-app="tournaments"] #scsRoleWorkspaceChooser .scs-role-sport-picker,
html[data-scs-app="tournaments"] #scsRoleWorkspaceChooser .scs-welcome-default,
html[data-scs-app="tournaments"] #scsRoleWorkspaceChooser #scsWelcomeSettings{display:none!important}
html[data-scs-app="tournaments"] #scsRoleWorkspaceChooser h1{font-size:clamp(26px,6vw,34px);line-height:1.2}
html[data-scs-app="tournaments"] #scsCentralClubName{overflow-wrap:anywhere}

/* V941: disabled downstream event pages retain readable labels and touch targets. */
.scs-four-tab-nav button:disabled{opacity:.42;cursor:not-allowed;filter:grayscale(.6)}
.scs-event-readiness{font-size:16px;line-height:1.5;color:var(--text,#fff);border-left:3px solid #f5bb50;padding:10px 12px;margin:12px 0;background:rgba(245,187,80,.08)}

/* V942: Event Assist stays open while setup is incomplete. */
.scs-event-setup-assist{border:1px solid var(--border,#607b98);border-left:3px solid #f5bb50;border-radius:12px;padding:14px;margin:12px 0;background:var(--card,#12304b)}
.scs-event-setup-assist h3{margin:0 0 6px;font-size:20px}
.scs-event-assist-progress{font-size:16px;margin:0 0 12px;color:var(--text-dim,#b6c7dc)}
.scs-event-assist-steps{list-style:none;padding:0;margin:0}
.scs-event-assist-steps li{border-bottom:1px solid var(--border,#607b98)}
.scs-event-assist-steps li:last-child{border-bottom:0}
.scs-event-assist-steps li>button,.scs-event-assist-steps li>span{display:flex;align-items:center;gap:10px;width:100%;min-height:44px;padding:10px 0;border:0;border-radius:0;background:transparent;color:inherit;text-align:left;font:600 16px/1.4 system-ui;box-sizing:border-box}
.scs-event-assist-steps button{cursor:pointer}
.scs-event-assist-steps button:disabled{opacity:.6;cursor:default}
.scs-event-assist-steps small{margin-left:auto;font-size:12px;white-space:normal;text-align:right;font-weight:400;max-width:90px}
.scs-event-assist-mark{flex:0 0 22px;text-align:center;color:#f5bb50;font-size:20px}
.scs-event-assist-steps .is-complete .scs-event-assist-mark{color:#55d4ae}
.scs-event-assist-message{margin:12px 0 0;font-size:16px;line-height:1.5}

/* V943: reserve actual fixed-bar height, including iOS safe-area padding. */
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament)[data-scs-workspace-bounded]{bottom:var(--scs-workspace-bottom,0px)!important;height:auto!important;max-height:none!important;padding-bottom:12px!important;box-sizing:border-box!important;scroll-padding-bottom:12px}
.scs-tm-entry-modal{top:max(env(safe-area-inset-top,0px),var(--scs-workspace-top,0px))!important;bottom:var(--scs-workspace-bottom,0px)!important;height:auto!important;padding:10px!important;box-sizing:border-box!important;overflow:hidden!important}
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament) .scs-tm-entry-modal .scs-tm-entry-editor{position:relative!important;display:flex!important;flex-direction:column!important;width:min(100%,560px)!important;min-height:0!important;max-height:100%!important;overflow:hidden!important;box-sizing:border-box!important;padding:16px 12px 10px!important;margin:0 auto!important}
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament) .scs-tm-entry-editor > h3{flex-shrink:0;margin:0 40px 8px 0!important;font-size:20px;line-height:1.3}
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament) .scs-tm-entry-editor > p{flex-shrink:0;margin:6px 0 10px!important;font-size:16px;line-height:1.4}
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament) .scs-tm-entry-editor > :has(> .scs-shared-pick-list){display:flex!important;flex-direction:column!important;flex:1 1 auto!important;min-height:0!important;overflow:hidden!important}
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament) .scs-tm-entry-editor .scs-shared-pick-count{flex-shrink:0;margin:4px 0!important}
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament) .scs-tm-entry-editor .scs-shared-pick-list{flex:1 1 auto!important;min-height:0!important;max-height:none!important;overflow-y:auto!important;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;padding-bottom:4px;scroll-padding-bottom:4px}
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament) .scs-tm-entry-editor .scs-tm-entry-player-preview{flex-shrink:0;max-height:72px;overflow:auto}
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament) .scs-tm-entry-modal .scs-tm-import-actions{position:static!important;flex:0 0 auto!important;display:flex!important;gap:10px;margin:8px 0 0!important;padding:8px 0 0!important;background:inherit!important}
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament) .scs-tm-entry-modal .scs-tm-import-actions button{min-height:44px;font-size:16px;flex:1}
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament) .scs-tm-entry-modal .scs-tm-entry-status:empty{display:none!important}
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament) .scs-tm-entry-modal .scs-tm-entry-close{top:8px!important;right:8px!important}

/* V944: navigation stays visible; dialogs occupy only the workspace above it. */
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament):has(.scs-tm-entry-modal) > .scs-tm-bottom-nav{display:grid!important;visibility:visible!important}
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament) .scs-tm-entry-modal{top:max(env(safe-area-inset-top,0px),var(--scs-workspace-top,0px))!important;bottom:var(--scs-workspace-bottom,0px)!important;height:auto!important;padding:10px!important;box-sizing:border-box!important}
/* Shared full-roster picker: only its content scrolls, never its action footer. */
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament) .scs-tm-entry-editor > .scs-team-club-scroll{flex:1 1 auto!important;min-height:0!important;overflow-y:auto!important;overscroll-behavior:contain;-webkit-overflow-scrolling:touch}

/* V945: the full-screen shell owns navigation; only its content pane scrolls. */
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament).scs-workspace-shell{bottom:0!important;height:auto!important;padding:0!important;overflow:visible!important}
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament) > [data-scs-workspace-content]{position:absolute;top:0;left:0;right:0;bottom:var(--scs-workspace-bottom,0px);min-height:0;overflow-x:hidden;overflow-y:auto;box-sizing:border-box;padding:12px;scroll-padding-bottom:12px;overscroll-behavior:contain;-webkit-overflow-scrolling:touch}
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament).scs-workspace-shell > nav.scs-tm-bottom-nav{position:fixed!important;bottom:0!important;left:0!important;right:0!important;display:grid!important;visibility:visible!important;overflow:visible!important;transform:none!important}
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament).scs-workspace-shell > nav.scs-four-tab-nav .scs-tm-nav-icon{display:block!important;visibility:visible!important;opacity:1!important;flex:none!important;width:26px!important;height:26px!important}
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament).scs-workspace-shell > nav.scs-four-tab-nav .scs-tm-nav-icon svg{display:block!important;visibility:visible!important;opacity:1!important;width:26px!important;height:26px!important}
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament).scs-workspace-shell > nav.scs-four-tab-nav .scs-tm-nav-label{display:block!important;visibility:visible!important}
#scsGroupTournament > [data-scs-workspace-content] > .scs-gt-sheet:not(.scs-team-sheet){background:transparent!important}
#scsTournamentOverlay.scs-ko-players-step > [data-scs-workspace-content] > section:not(.scs-tm-entry-modal){padding:8px!important}
@media(max-width:480px){:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament) > [data-scs-workspace-content]{padding:8px}}

/* V949: every tournament page scrolls between the actual header and navigation. */
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament) > [data-scs-workspace-content]{top:var(--scs-workspace-top,0px);scroll-padding-top:12px;isolation:isolate}
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament) > [data-scs-workspace-content] > :is(.scs-gt-sheet,.scs-team-sheet){position:relative!important;top:auto!important;bottom:auto!important;height:auto!important;max-height:none!important;min-height:0!important;margin-top:0!important;margin-bottom:0!important;overflow:visible!important;box-sizing:border-box}
:is(#scsTournamentManager,#scsTournamentContinue,#scsTournamentTypePicker,#scsTournamentLive)[data-scs-workspace-bounded]{top:var(--scs-workspace-top,0px)!important;bottom:var(--scs-workspace-bottom,0px)!important;min-height:0!important;height:auto!important;overflow-y:auto!important;overflow-x:hidden!important;scroll-padding:12px;padding-top:12px!important;padding-bottom:12px!important}
/* Nested editors stay within the same usable area and scroll independently. */
:is(#scsTournamentOverlay,#scsGroupTournament,#scsTeamTournament) :is(.scs-tm-entry-modal,.scs-shared-pair-overlay){max-width:100%;box-sizing:border-box}
.scs-shared-pair-panel{max-height:100%;min-height:0;overflow-y:auto;box-sizing:border-box}
/* Pair pickers and result sheets are workspaces too, not full-screen covers. */
.scs-shared-pair-overlay,.scs-team-matrix-overlay{top:var(--scs-workspace-top,0px)!important;bottom:var(--scs-workspace-bottom,0px)!important;height:auto!important;min-height:0!important;overflow:hidden!important}
.scs-team-matrix-bottom-sheet{max-height:100%!important;min-height:0}
.scs-team-matrix-sheet-content{min-height:0}
body > #scs-api-create-overlay{top:var(--scs-workspace-top,0px)!important;bottom:var(--scs-workspace-bottom,0px)!important;min-height:0!important;height:auto!important;overflow-y:auto!important}

/* V952: Group Chart uses the shared Match Center result card. */
.scs-group-matrix-result{padding:12px;box-sizing:border-box}
.scs-group-matrix-result .scs-tm-completed-row{margin:0;width:100%;box-sizing:border-box}

/* V953: saved-score viewer always has an independent exit. */
#scsScoringOverlay #scsScoreViewDone{position:fixed!important;top:calc(env(safe-area-inset-top,0px) + 12px)!important;right:16px!important;z-index:2147483647!important;display:block!important;min-height:44px;padding:10px 20px;border:1px solid #73bcb9;border-radius:10px;background:#164b60;color:#fff;font:600 16px system-ui;box-shadow:0 2px 8px #0004}
#scsScoringOverlay #scsScoreViewDone[hidden]{display:none!important}

/* V956: one Scoreboard title in its shared header, with contextual Help. */
html[data-scs-app="scoreboard"]:has(#scsScoreboardAppHome:not([hidden])) #scsPracticeSharedHeader{display:block!important}
html[data-scs-app="scoreboard"] #scsScoreboardAppHome h1{display:none}


/* V960: tournament Events / Courts dashboard tabs. */
.scs-tournament-home-tabs{display:flex;gap:0;border-bottom:1px solid #45617f;margin:18px 0}
.scs-tournament-home-tabs [role="tab"]{flex:1;min-height:48px;padding:12px;font:600 16px system-ui;color:var(--sport-muted,#b6c8df);border:0!important;border-bottom:3px solid transparent!important;border-radius:0!important;background:transparent!important;box-shadow:none!important}
.scs-tournament-home-tabs [aria-selected="true"]{color:#6bd9d1;border-bottom-color:#6bd9d1!important}
.scs-tournament-home-tabs [role="tab"]:focus-visible{outline:2px solid #6bd9d1;outline-offset:-3px}
.scs-tournament-home-tabs~[role="tabpanel"][hidden]{display:none!important}
.scs-tournament-courts-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}
.scs-tournament-courts-heading h2{margin:0}.scs-tournament-courts-heading button{min-height:44px;font-size:16px}
.scs-tournament-court{margin:16px 0;border:1px solid var(--sport-line,#45617f);border-radius:12px;padding:12px;min-width:0}
.scs-tournament-court>h3{margin:0 0 10px;font-size:18px}
.scs-tournament-court-free{color:var(--sport-muted,#adc4d9)}
.scs-tournament-court .scs-tm-court-card{margin:12px 0 0;max-width:100%;box-sizing:border-box}
.scs-tournament-court-total,[data-courts-status]{font-size:16px;line-height:1.5}

.scs-api-home-host .scs-team-event-home>[role="tabpanel"]>button[data-add-event]{display:block!important;box-sizing:border-box!important;width:100%!important;min-height:50px!important;margin:22px 0 0!important;padding:12px 18px!important;border-radius:12px!important;border:1px solid #558eea!important;background:#3067bd!important;color:#fff!important;font:inherit!important;font-size:1rem!important;font-weight:750!important;text-align:center!important;cursor:pointer;}

/* V961: tournament-wide court count is configured in Courts. */
.scs-tournament-court-settings{display:flex;align-items:flex-end;gap:12px;margin:18px 0;flex-wrap:wrap}
.scs-tournament-court-settings label{display:flex;flex:1;min-width:120px;flex-direction:column;gap:8px;font-size:16px}
.scs-tournament-court-settings input{box-sizing:border-box;width:100%;min-height:44px;padding:10px;border:1px solid var(--sport-line,#617c9f);border-radius:8px;background:var(--sport-surface,#112a49);color:inherit;font:16px system-ui}
.scs-tournament-court-settings button{min-height:44px;padding:10px 16px;font-size:16px}

.scs-event-court-pool-status{font-size:16px;line-height:1.5;padding:10px 12px;margin:8px 0;border:1px solid var(--sport-line,#45617f);border-radius:10px;color:var(--sport-text,#e4edf8)}

/* V964: tournament-wide upcoming matches, in the bounded workspace. */
.scs-tournament-home-tabs [role="tab"]{min-width:0;padding:12px 6px;font-size:15px;line-height:1.3}
.scs-tournament-assignment-filter{display:flex;flex-direction:column;gap:8px;margin:16px 0;font-size:16px}
.scs-tournament-assignment-filter select{width:100%;box-sizing:border-box;min-height:46px;border:1px solid var(--sport-line,#617c9f);border-radius:8px;background:var(--sport-surface,#112a49);color:inherit;padding:10px;font:inherit}
.scs-tournament-assignment-event{min-width:0;margin:20px 0}
.scs-tournament-assignment-event>h3{display:flex;flex-wrap:wrap;align-items:baseline;justify-content:space-between;gap:8px;margin:0 0 12px}
.scs-tournament-assignment-event>h3 span{font-size:14px;font-weight:400;color:var(--sport-muted,#b6c8df)}
.scs-tournament-assignment-match{border:1px solid var(--sport-line,#45617f);border-radius:12px;padding:14px;margin:12px 0;min-width:0;background:transparent}
.scs-tournament-assignment-label{display:flex;flex-wrap:wrap;justify-content:space-between;gap:8px;margin-bottom:14px}
.scs-tournament-assignment-label small,.scs-tournament-assignment-summary{color:var(--sport-muted,#b6c8df)}
.scs-tournament-assignment-pairs{display:grid;grid-template-columns:minmax(0,1fr);gap:10px}
.scs-tournament-assignment-pairs>div{display:flex;flex-direction:column;gap:8px;min-width:0}
.scs-tournament-assignment-pairs .scs-match-player-identity{min-width:0;max-width:100%}
.scs-tournament-assignment-pairs .scs-match-player-name{min-width:0;overflow-wrap:anywhere}
.scs-tournament-assignment-vs{font-size:13px;color:var(--sport-muted,#b6c8df);text-align:center;text-transform:uppercase}
.scs-tournament-assignment-action{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px;border-top:1px solid var(--sport-line,#45617f);margin-top:14px;padding-top:12px}
.scs-tournament-assignment-action>span{font-size:14px;color:var(--sport-muted,#b6c8df)}
.scs-tournament-assignment-action>button{min-height:44px;min-width:120px;padding:10px 16px;border:1px solid #54d7cc;border-radius:8px;background:#215c93;color:#fff;font:600 16px system-ui}
.scs-tournament-assignment-action>button:disabled{opacity:.55;border-color:var(--sport-line,#45617f);cursor:default}
.scs-court-assignment-error{color:#ffb7ae;font-size:15px;line-height:1.5}
.scs-court-assignment-error:empty{display:none}
